window.__T__=[{"i":8160,"text":"一张精致的摄影肖像，主体为 {argument name=\"subject\" default=\"年轻东亚女性\"}，半身像，居中面向前方，背景为平滑的深炭灰色，带有微妙的晕影灯光效果。她留着长而有光泽、微卷的 {argument name=\"hair color\" default=\"黑色\"} 头发，垂在双肩两侧，配有柔和的直刘海和整齐的中分发线。她穿着一件剪裁考究的双排扣 {argument name=\"blazer color\" default=\"深海军蓝\"} 西装外套，带有 6 枚明显的圆形金色徽章纽扣，营造出优雅的专业形象。她的右手若有所思地抬起托在下巴下方，手指放松，呈现出端庄的正式姿态。使用来自左前方的柔和定向摄影灯光，呈现高细节的皮肤纹理、逼真的面料质感、柔和的阴影以及高级商务头像的审美。画面采用竖构图，简洁明快，主体占据画面大部分空间。在左下角添加 1 张白色背景的小型矩形嵌入式对比照片，展示同一位女性穿着白色翻领衬衫的简约证件照风格，并在嵌入图下方或上方叠加显示 {argument name=\"corner text\" default=\"GPT Image2\"} 字样，使用醒目的黑色无衬线字体。超写实，精致，具备编辑级肖像品质。","imgs":["https://r2.qqsrc.com/images/originals/15317.jpg"]},{"i":8161,"text":"{\"type\":\"并排模型对比海报\",\"subject\":\"戏剧性的足球进球庆祝\",\"style\":\"电影感体育摄影对比，高能量，写实，编辑类社交媒体图形\",\"layout\":{\"orientation\":\"垂直\",\"sections\":[{\"title\":\"GPT-image-2\",\"position\":\"上半部分\",\"count\":1,\"labels\":[\"GPT-image-2\"]},{\"title\":\"Nano Banana 2\",\"position\":\"下半部分\",\"count\":1,\"labels\":[\"Nano Banana 2\"]}],\"divider\":\"一条粗水平白线将两张图像分隔开\",\"border\":\"左右边缘带有黑色胶片边框，两侧各有均匀分布的白色链轮孔，每侧约 15 个孔\",\"watermarks\":[{\"text\":\"GPT-image-2\",\"position\":\"顶部面板右下角区域\"},{\"text\":\"Nano Banana 2\",\"position\":\"底部面板右上角区域\"}]},\"scene\":{\"sport\":\"足球\",\"moment\":\"一名球员进球后，双膝跪地滑向镜头，双臂张开，队友从后方奔跑而来\",\"camera\":\"低机位球场视角，略微广角，主角居中，动态透视\",\"environment\":\"夜间满座体育场，明亮的泛光灯下，模糊的欢呼人群，鲜艳的绿草地，飞溅的草皮碎片\"},\"panels\":{\"top\":{\"look\":\"欧冠风格比赛照片，色调较暗且对比度高，具有广播级的写实感\",\"main player\":{\"kit\":\"黑色球衣球裤，带有金色字母和饰边\",\"pose\":\"双膝跪地滑向镜头，躯干略微后仰，双臂张开\"},\"teammates\":{\"count\":4,\"descriptions\":[\"一名队友在后方居中位置向前奔跑\",\"一名队友在右侧张开双臂奔跑，佩戴队长袖标\",\"一名队友在左后方背景中举起双臂\",\"一名远处的队友在右后方背景中\"]},\"crowd\":\"密集的蓝色调体育场人群，高度模糊\",\"text_overlay\":\"大号粗体白色无衬线文字，内容为 GPT-image-2\"},\"bottom\":{\"look\":\"更通用但具有戏剧性的体育照片，明亮的体育场雾气，写实感稍显柔和\",\"main player\":{\"kit\":\"纯浅灰色或白色球衣球裤\",\"pose\":\"双膝跪地滑向镜头，双臂张开，腿部附近踢起泥土和草屑\"},\"teammates\":{\"count\":5,\"descriptions\":[\"一名队友在最左侧向前奔跑\",\"一名队友在中心左侧屈膝跳跃\",\"一名队友在中心右后方奔跑\",\"一名队友在中心右侧向庆祝人群奔跑\",\"一名队友在最右侧双拳高举\"]},\"crowd\":\"欢呼的观众，可见几面红白绿旗帜\",\"lighting\":\"明亮的头顶体育场灯光，带有大气光晕\",\"text_overlay\":\"大号粗体白色无衬线文字，内容为 Nano Banana 2\",\"extra_mark\":\"右下角附近有一个白色小闪光图标\"}},\"quality\":\"高细节，动感，浅景深，逼真的皮肤和织物纹理，戏剧性的体育动作，社交媒体对比美学\",\"avoid\":\"卡通风格，空旷的体育场，静态姿势，特写裁剪，除可见对比文字外的其他标志\"}","imgs":["https://r2.qqsrc.com/images/originals/15318.jpg"]},{"i":8162,"text":"一张极具戏剧性的日本拳击赛海报，采用精致的动漫插画风格，垂直构图，从中间一分为二，左侧为暖金色，右侧为电光蓝。最上方是巨大的金属质感金色浮雕字体，内容为 {argument name=\"headline text\" default=\"JUNGLE PREMIUM Vol.7\"}，带有明亮的光晕和 3D 斜面效果。正下方居中处是白色的日文文字“世界4団体フェザー級タイトルマッチ”。画面展示了 2 位羽量级男性拳击手在拳击台内对峙的全身像，两人肌肉发达、体格精瘦，皮肤带有光泽感。左侧拳击手是一位金发动漫风格青年，短发凌乱，戴着金色拳击手套，身穿黑金配色短裤（其中一条腿上有红白装饰），黑色拳击靴配金色鞋带，腰带上印有“SEIJI”字样。他站在金色一侧，周围环绕着爆发性的金色火花和光束。右侧拳击手是一位黑发动漫风格青年，短发尖刺状，戴着亮蓝色拳击手套，身穿深海军蓝短裤，蓝色拳击靴配白袜，腰带上印有“JUNICHI”字样。他站在蓝色一侧，周围环绕着旋转的蓝色能量、光轨和发光粒子。在两人之间的背景中心放置一个圆形冠军腰带徽章，后方可见拳击台绳索，腰带奖章上清晰可见“WORLD CHAMPION”字样。在背景中添加 2 个巨大的淡化肖像叠层，每位拳击手身后各一个：左侧背景肖像呈金色调，右侧背景肖像呈蓝色调。在最左侧，放置发着白金光芒的粗体垂直日文书法“黄金の閃光”。在最右侧，放置发着蓝白光芒的粗体垂直日文书法“蒼き鉄拳”。底部展示 2 个巨大的日文姓名块：左侧为金色“松浦聖司”，右侧为冰蓝白色“藤原潤一”，中间是一个燃烧的金色“VS”。下方居中处是巨大的白色日期文字 {argument name=\"event date\" default=\"7月19日(日)\"}。最底部居中处是金色的衬线字体 {argument name=\"venue name\" default=\"SUN BIRTH STADIUM\"}。运用极致对比度、电影级竞技场灯光、动感的粒子特效、高端体育赛事海报设计、光泽感排版以及英雄般的高风险冠军赛氛围。","imgs":["https://r2.qqsrc.com/images/originals/15321.jpg"]},{"i":8163,"text":"{\"type\":\"动漫拳击赛事海报\",\"style\":\"戏剧性日式格斗海报，高光高对比度数字插画，肌肉感少年漫美学，强烈的竞技场灯光，火花与能量流，高级金属质感排版，宣传主视觉图\",\"event\":{\"header_small\":\"Nekome Höseki Promotion & Bullet Promotion 联合呈现\",\"headline\":\"Cat's Eye Boxing Vol.5 × 玫瑰之弹\",\"date\":\"6月19日 (周五)\",\"venue\":\"一拳东市体育馆\",\"ticket_banner\":\"门票火热发售中！\",\"footer_notes\":[\"主办：猫目宝石推广／Bullet 推广\",\"协办：拳东市拳击协会 后援：拳东市／拳东市委员会\",\"咨询：Cat's Eye Boxing 事务局 电话：03-1234-5678\"]},\"layout\":{\"orientation\":\"竖版海报\",\"sections\":[{\"title\":\"决赛\",\"position\":\"上中\",\"count\":2,\"subtitle\":\"51.5kg 契约战\",\"matchup\":{\"left_name\":\"纳特·伊提蓬猜\",\"right_name\":\"山本京介\"}},{\"title\":\"半决赛\",\"position\":\"下中\",\"count\":2,\"subtitle\":\"日本青年冠军赛 8 回合\",\"matchup\":{\"left_name\":\"日入雷欧\",\"right_name\":\"一条凛吾\"}},{\"title\":\"票价\",\"position\":\"左下\",\"count\":4,\"labels\":[\"SRS 席 15,000 日元\",\"RS 席 10,000 日元\",\"指定 A 席 7,000 日元\",\"指定 B 席 5,000 日元\"]},{\"title\":\"当日票通知\",\"position\":\"右下\",\"count\":2,\"labels\":[\"提供当日票\",\"开场 16:00\",\"比赛开始 17:00\"]}],\"center_dividers\":2},\"fighters\":{\"count\":4,\"top_left\":{\"role\":\"决赛左侧选手\",\"build\":\"紧凑、精瘦、肌肉发达\",\"skin_tone\":\"古铜色\",\"hair\":\"短款深色尖刺发型\",\"gloves\":\"亮红色拳击手套\",\"trunks\":\"带有白红侧条纹的蓝色拳击短裤\",\"pose\":\"正架防守，左手套靠近脸部，右手套向前，躯干朝向中心\",\"side_effects\":\"被红色光流和火花环绕\"},\"top_right\":{\"role\":\"决赛右侧选手\",\"build\":\"身材高大、肌肉极其发达、胸部和手臂宽阔\",\"skin_tone\":\"浅古铜色\",\"hair\":\"中长棕色后梳发型，带有几缕碎发\",\"gloves\":\"蓝色拳击手套\",\"trunks\":\"带有厚白色腰带的绿色拳击短裤\",\"pose\":\"向内倾斜的防守姿态，双手套举起，占据前景主导地位\",\"side_effects\":\"被蓝色光流和火花环绕\"},\"bottom_left\":{\"role\":\"半决赛左侧选手\",\"build\":\"精瘦且肌肉线条明显\",\"skin_tone\":\"浅古铜色\",\"hair\":\"短深色发型\",\"gloves\":\"红色拳击手套\",\"trunks\":\"带有红色腰带的深色短裤\",\"pose\":\"面向中心的紧凑防守姿态\"},\"bottom_right\":{\"role\":\"半决赛右侧选手\",\"build\":\"精瘦且肌肉线条清晰\",\"skin_tone\":\"苍白\",\"hair\":\"短银白色发型\",\"gloves\":\"蓝色拳击手套\",\"trunks\":\"带有白色腰带的蓝色短裤，可见 'REXEX' 和 'BXXN' 文字补丁\",\"pose\":\"面向中心的防守姿态\",\"details\":\"左肩有小型黑色纹身状徽章\"}},\"background\":{\"setting\":\"座无虚席的室内拳击竞技场\",\"ring\":{\"visible\":true,\"ropes_count\":3},\"crowd\":\"黑暗的观众剪影和远处的观众\",\"lighting\":\"红蓝对决的色彩方案，左侧为炽热的红色，右侧为电光蓝色，明亮的镜头光晕，头顶射灯，余烬颗粒\",\"text_style\":{\"main_title\":\"大型做旧金色笔刷字体\",\"section_titles\":\"巨大的金属质感金色衬线大写字母\",\"fighter_names\":\"红蓝斜切名牌上的粗体日文字体\",\"overall\":\"电影感、震撼、冠军赛海报排版\"}}","imgs":["https://r2.qqsrc.com/images/originals/15322.jpg"]},{"i":8164,"text":"{\"type\":\"旅游杂志与移动应用宣传样机\",\"theme\":\"浪漫东京夜游品牌设计\",\"brand\":{\"name\":\"{argument name=\\\"brand name\\\" default=\\\"旅色\\\"}\",\"romanized\":\"TABIIRO\",\"tagline\":\"Tokyo Night Trip\"},\"style\":{\"overall\":\"奢华编辑设计与现代旅游应用 UI 展示的融合\",\"color_palette\":\"深海军蓝、黑色、暖金色、柔粉色、白色、城市灯光虚化效果\",\"lighting\":\"电影质感的夜间光影，伴随闪烁的城市灯光与暖色高光\",\"mood\":\"优雅、浪漫、令人向往、高端\"},\"subject\":{\"primary_model\":\"一位迷人的东亚成年女性，身穿修身闪亮玫瑰金长袖晚礼服，留着齐肩深色波波头，在俯瞰东京夜景的阳台栏杆旁若有所思地摆姿势\",\"setting\":\"高层露台或屋顶，背景可见虚化的天际线和东京塔\"},\"layout\":{\"composition\":\"多面板营销项目，展示了杂志封面、跨页、网站着陆页及智能手机应用界面\",\"sections\":[{\"title\":\"杂志封面\",\"position\":\"左上\",\"count\":1,\"labels\":[\"旅色\",\"Tokyo Night Trip\",\"东京的夜，心动的旅程。\",\"封面：探索东京的女性\",\"特别专访：重新发现东京的魅力\",\"今夏必去的 10 个东京景点\"]},{\"title\":\"杂志跨页\",\"position\":\"中上\",\"count\":1,\"labels\":[\"第 56 期\",\"8\",\"恋上东京的夜。\",\"璀璨城市与特别时光。\",\"看点\",\"01 绝景\",\"02 美食\",\"03 文化与体验\"]},{\"title\":\"天气与城市信息面板\",\"position\":\"右上\",\"count\":1,\"labels\":[\"东京实时天气\",\"27°C\",\"晴转多云\",\"湿度：62%\",\"风速：2.1m/s\",\"体感温度：28°C\",\"2024.5.20 15:00 更新\"]},{\"title\":\"智能手机应用界面\",\"position\":\"右侧\",\"count\":1,\"labels\":[\"旅色\",\"东京的夜，心动的旅程。\",\"推荐景点\",\"专题\",\"首页\",\"搜索\",\"旅行手册\",\"通知\",\"个人中心\"]},{\"title\":\"网站着陆页\",\"position\":\"左下及中部\",\"count\":1,\"labels\":[\"旅色\",\"东京的夜，心动的旅程。\",\"与旅色一起，留下难忘的体验。\",\"立即下载\",\"从 App Store 下载\",\"在 Google Play 获取\",\"选择旅色的 3 大理由\",\"精选推荐景点\",\"定制你的专属旅行计划\",\"实时天气与资讯\",\"热门区域\"]},{\"title\":\"热门区域行\",\"position\":\"中下\",\"count\":5,\"labels\":[\"六本木\",\"浅草\",\"丸之内\",\"中目黑\",\"台场\"]},{\"title\":\"应用内专题缩略图\",\"position\":\"手机内中右侧\",\"count\":6,\"labels\":[\"六本木新城展望台\",\"浅草寺\",\"中目黑夜樱\",\"霓虹街区\",\"东京美食之旅\",\"大人的东京漫步\"]},{\"title\":\"理由图标行\",\"position\":\"中下上方\",\"count\":3,\"labels\":[\"精选推荐景点\",\"定制你的专属旅行计划\",\"实时天气与资讯\"]},{\"title\":\"底部服务功能行\",\"position\":\"网站面板最底部\",\"count\":4,\"labels\":[\"提供最新旅游资讯\",\"丰富的评价与口碑\",\"支持离线使用\",\"轻松创建旅行手册\"]}],\"inset_images\":{\"count\":2,\"descriptions\":[\"烛光餐厅中精致的餐盘与美酒\",\"同一位女性在城市灯光背景下的阳台半身像\"]}},\"background\":{\"surface\":\"整洁的浅色桌面或演示板\",\"arrangement\":\"重叠的印刷页面与数字屏幕，呈现出品牌案例研究的效果\"},\"rendering\":{\"quality\":\"高分辨率商业样机\",\"camera\":\"略微仰视的正面视角，清晰捕捉所有面板\",\"detail_level\":\"清晰的排版、光泽印刷质感、逼真的手机硬件、精致的 UI 卡片\"},\"customization\":{\"city\":\"{argument name=\\\"city\\\" default=\\\"Tokyo\\\"}\",\"main headline\":\"{argument name=\\\"main headline\\\" default=\\\"东京的夜，心动的旅程。\\\"}\",\"temperature\":\"{argument name=\\\"temperature\\\" default=\\\"27°C\\\"}\",\"dress color\":\"{argument name=\\\"dress color\\\" default=\\\"玫瑰金闪光\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/15324.jpg"]},{"i":8165,"text":"制作一张大胆的日式 YouTube 缩略图，主题为 {argument name=\"headline text\" default=\"初心者でもできる AI×動画編集\"}，采用未来感霓虹蓝赛博朋克风格。使用 16:9 宽屏构图，背景为深电蓝色，布满发光的电路线条、数字条纹、镜头光晕和高能量的动态效果。在左上角放置一个倾斜的发光横幅，包含日文文本 {argument name=\"top banner text\" default=\"初心者でもできる\"}，其中第一部分为亮黄色，其余部分为白色。主标题应占据左侧和中心位置：巨大的白色发光文字“AI×”位于更大的白色发光文字“動画編集”上方，带有厚实的蓝色霓虹外发光、轻微的前倾斜动态感、斜面 3D 阴影和强烈的透视效果。在右上角，添加一个圆形全息界面，中心带有字母 {argument name=\"ai badge text\" default=\"AI\"}，周围环绕着同心圆和微小的 HUD 标记。在其附近，包含 3 个浮动的应用风格图标：一个播放按钮图标、一个方形“Pr”图标和一个音频波形图标，全部呈现蓝色发光效果。在右下角，展示一个时尚的倾斜视频剪辑监视器，显示霓虹城市夜景道路场景，并覆盖有播放符号；在预览下方，包含一个时间轴，显示 4 个可见轨道：2 行视频缩略图和 2 条彩色音频条，分别为洋红色和青绿色。在底部，添加 3 个发光的圆形功能徽章，带有图标和日文文本：带有“知識ゼロOK”的书本图标、带有“時短でカンタン”的时钟图标以及带有“プロ級の仕上がり”的闪光图标。在顶部中心偏右处添加一个高大的纯蓝色垂直矩形作为占位块。整体设计应具有动态感、高对比度、精致感和科技感，并针对现代 AI 和视频剪辑教程缩略图的最高点击率进行了优化。","imgs":["https://r2.qqsrc.com/images/originals/15326.jpg"]},{"i":8166,"text":"{\"type\":\"奇幻商品目录海报\",\"theme\":\"鸭子主题游戏联盟的官方周边公告\",\"style\":\"精致的促销产品单，奇幻游戏美学，日式零售传单，羊皮纸与金色 UI 边框，精细的商业样机，装饰性海报中嵌入整洁的摄影棚产品渲染图\",\"brand\":{\"name\":\"{argument name=\\\"organization name\\\" default=\\\"日本鸭同盟\\\"}\",\"headline\":\"{argument name=\\\"headline text\\\" default=\\\"日本鸭同盟 官方周边\\\"}\",\"tagline\":\"与伙伴一起，将快乐化为实体！\",\"logo\":\"一枚纹章盾牌，中心为带有橙色喙的亮绿色鸭头，背景为蓝红装饰，带有小字 EMPIRES & PUZZLES 以及大字 JAPAN KAMO ALLIANCE\"},\"canvas\":{\"orientation\":\"portrait\",\"background\":\"陈旧的奶油色目录纸，由华丽的深海军蓝与金色奇幻边框及装饰性边角花纹环绕\"},\"header\":{\"count\":4,\"elements\":[\"左上角联盟纹章 Logo\",\"顶部居中的大型金色日文标题\",\"标题下方的小型白色日文标语\",\"右上角张开翅膀的卡通鸭子吉祥物，站在色彩斑斓的拼图宝石旁，远处为奇幻城堡天际线，前方有一盏发光的灯笼\"]},\"layout\":{\"sections\":[{\"title\":\"服饰\",\"position\":\"上半部分\",\"count\":3,\"items\":[{\"label\":\"联盟 Logo T 恤\",\"price\":\"¥3,300 (含税)\",\"description\":\"海军蓝短袖 T 恤，展示正面及侧面/背面，胸前印有大型纹章 Logo，背面印有竖排日文\"},{\"label\":\"联盟 Logo 连帽衫\",\"price\":\"¥6,800 (含税)\",\"description\":\"黑色拉链连帽衫，展示正面及背面，左胸有小型纹章 Logo，背面有大型竖排金色日文\"},{\"label\":\"鸭子绅士 Polo 衫\",\"price\":\"¥4,200 (含税)\",\"description\":\"海军蓝 Polo 衫，左胸绣有小型鸭子纹章\"}]},{\"title\":\"杂货\",\"position\":\"中左侧\",\"count\":2,\"items\":[{\"label\":\"联盟 Logo 马克杯\",\"price\":\"¥1,650 (含税)\",\"description\":\"白色陶瓷马克杯，侧面印有纹章 Logo\"},{\"label\":\"鸭子纹章随行杯\",\"price\":\"¥2,200 (含税)\",\"description\":\"黑色保温随行杯，带有金属杯口，正面印有纹章 Logo\"}]},{\"title\":\"吉祥物\",\"position\":\"中中央\",\"count\":1,\"items\":[{\"label\":\"鸭子骑士毛绒公仔\",\"price\":\"¥2,800 (含税)\",\"description\":\"绿色鸭子吉祥物毛绒玩具，身穿棕色奇幻盔甲，胸前带有徽章，呈坐姿正面朝向\"}]},{\"title\":\"文具\",\"position\":\"中右侧\",\"count\":2,\"items\":[{\"label\":\"联盟笔记本\",\"price\":\"¥880 (含税)\",\"description\":\"深海军蓝笔记本，带有竖排金色日文标题，底部有小型鸭子图标\"},{\"label\":\"联盟圆珠笔\",\"price\":\"¥660 (含税)\",\"description\":\"黑色圆珠笔，带有金色装饰及金色日文字样\"}]},{\"title\":\"配饰\",\"position\":\"下左侧\",\"count\":2,\"items\":[{\"label\":\"Logo 钥匙扣\",\"price\":\"¥990 (含税)\",\"description\":\"联盟纹章形状的金属钥匙扣\"},{\"label\":\"徽章胸针\",\"price\":\"¥770 (含税)\",\"description\":\"小型纹章形状的珐琅胸针\"}]},{\"title\":\"其他\",\"position\":\"下右侧\",\"count\":2,\"items\":[{\"label\":\"联盟迷你旗帜\",\"price\":\"¥1,100 (含税)\",\"description\":\"小型竖排海军蓝旗帜，带有金色日文及鸭子图标，配有底座\"},{\"label\":\"鸭子贴纸套装\",\"price\":\"¥550 (含税)\",\"description\":\"贴纸页，包含 6 款鸭子主题奇幻角色贴纸及 JAPAN KAMO ALLIANCE 标题\"}]}],\"total products\":12},\"footer\":{\"count\":3,\"elements\":[\"左侧蓝金徽章条，文字为“全品原创设计!”\",\"中央蓝金徽章条，文字为“仅在此处可获得的限定商品!”\",\"右侧带有鸭子图标的蓝金徽章条，文字为“联盟的羁绊，常伴左右。”\"],\"disclaimer\":\"※图片仅供参考。实际商品可能有所不同。\"},\"color_palette\":{\"primary\":\"深海军蓝\",\"secondary\":\"古董金\",\"accent\":\"翡翠绿\",\"supporting\":\"奶油色、黑色、白色、暖棕色\"},\"rendering_notes\":\"每件产品均在浅奶油色背景上整齐剪裁，带有柔和阴影，排列在带有金色分隔线和蓝色标题标签的对称目录网格中。使用清晰易读的日文字体、高级奇幻游戏品牌形象以及高端官方周边广告外观。\",\"parameters\":[\"{argument name=\\\"organization name\\\" default=\\\"日本鸭同盟\\\"}\",\"{argument name=\\\"headline text\\\" default=\\\"日本鸭同盟 官方周边\\\"}\"]}","imgs":["https://r2.qqsrc.com/images/originals/15329.jpg"]},{"i":8167,"text":"{\"type\":\"动漫项目拼贴\",\"style\":\"高质量精致动漫插画，电影级光效，柔和光晕，动态感，生动的角色表演\",\"subject\":{\"main character\":{\"description\":\"一位娇小的天使女学生，长着巨大的发光白色羽翼，留着非常长的波浪形白发，侧边有一条小辫子，皮肤白皙，蓝色眼睛，身穿蓝色篮球训练背心，内搭白色运动 T 恤和深蓝色运动短裤\"},\"supporting characters\":{\"count\":5,\"description\":\"学校体育馆里的其他初中女生，大多身穿红色训练背心，内搭白色运动衫和深蓝色短裤，作为对手或队友做出反应\"}},\"setting\":{\"location\":\"日本室内学校体育馆\",\"details\":[\"高大的木质墙板\",\"大型阳光充足的窗户\",\"光亮的硬木球场\",\"篮球架和篮板\",\"温暖的午后阳光射入室内\"]},\"layout\":{\"composition\":\"2x2 四格项目页\",\"panels\":[{\"position\":\"左上\",\"count\":1,\"scene\":\"长翅膀的女孩在比赛中接球或伸手去接球，从球场视角拍摄，左前景有一名身穿蓝色背心的黑发女孩，周围有三名身穿红色背心的球员\",\"camera\":\"动态中远景\",\"effects\":[\"球悬在半空\",\"背光发光的翅膀\",\"体育动作感\"]},{\"position\":\"右上\",\"count\":1,\"scene\":\"天使女孩展开双翼跃向空中，单手持球飞向篮筐，下方三名女孩抬头惊愕地看着她\",\"camera\":\"戏剧性的低角度动作镜头\",\"effects\":[\"穿过羽毛的明亮轮廓光\",\"升空感和速度感\",\"飘动的头发和四肢\"]},{\"position\":\"左下\",\"count\":1,\"scene\":\"篮筐处的特写低角度扣篮，天使女孩用力将篮球扣入篮筐\",\"camera\":\"篮板附近的极端动态低角度镜头\",\"effects\":[\"篮网变形\",\"闪烁的光粒子\",\"翅膀填满画面\",\"下方观众举起的手\"]},{\"position\":\"右下\",\"count\":1,\"scene\":\"Q 版喜剧式结局：天使女孩双手交叉、鼓起脸颊，一脸得意地站着，周围四个女孩愤怒地向她抱怨\",\"camera\":\"正面 Q 版群像镜头\",\"effects\":[\"橙黄色漫画爆发背景\",\"漫画式的愤怒符号和蒸汽团\",\"夸张的叫喊表情\"]}]},\"character consistency\":{\"main outfit pieces\":[\"蓝色训练背心\",\"白色短袖运动衫\",\"深蓝色运动灯笼裤或短裤\",\"轻便运动鞋\"],\"main hair features\":[\"非常长的白发\",\"松散的波浪\",\"前额附近的小辫子\"],\"main wing features\":[\"两只巨大的发光白色羽翼\"]},\"prompt\":\"创建一个 {argument name=\\\"panel count\\\" default=\\\"4\\\"} 格动漫项目拼贴，展示 {argument name=\\\"character concept\\\" default=\\\"一位白发天使女学生在篮球比赛中大显身手\\\"}。在每一格中保持主角一致：一位娇小的女孩，留着 {argument name=\\\"hair color\\\" default=\\\"白色\\\"} 头发，巨大的发光羽翼，身穿 {argument name=\\\"uniform color\\\" default=\\\"蓝色\\\"} 篮球训练背心，场景位于阳光明媚的日本学校体育馆。第 1 格：动作传球/接球场景，有多名身穿红色背心的对手女孩。第 2 格：跃向篮筐，戏剧性的低角度，翅膀完全展开。第 3 格：从篮筐附近的下方看到的强力扣篮，闪烁的冲击效果，动态的篮筐和篮网。第 4 格：Q 版喜剧反应格，天使女孩得意地双手交叉，周围 4 个愤怒的女孩在叫喊。使用 {argument name=\\\"art style\\\" default=\\\"电影级精致动漫，带有柔和光晕和充满活力的体育动作感\\\"}。\"}","imgs":["https://r2.qqsrc.com/images/originals/15330.jpg"]},{"i":8168,"text":"一幅动漫奇幻女战士的全身插画，人物独自站立在纯浅灰色背景前，画面干净，采用柔和的绘画渲染风格与清晰的线条勾勒。她是一位身材苗条的年轻女性，留着一头长直发，{argument name=\"hair color\" default=\"白金色\"}，中分刘海修饰脸型，后方扎有一小束头发；拥有明亮的 {argument name=\"eye color\" default=\"琥珀棕色\"} 双眸，肤色白皙，神情沉稳且略带严肃。她的姿势充满动感与自信：双腿分开呈稳固站姿，一只手臂举过头顶，握住肩后的一柄长枪，另一只手在身侧下方握住枪身，使华丽的长枪在构图中呈对角线延伸。武器为 1 把精致的深色金属长枪，配有细长的枪刃、十字形倒钩、哥特风格雕刻细节以及锋利的枪尾。她的服装为精致的暗黑奇幻战斗装，包含 6 个清晰可见的主要部件：1 只带有雕刻甲片的黑色钢制右臂护手，1 件合身的黑铜色紧身胸甲，1 件白色高领衬衫配透明长袖，1 条不对称的白色短裙配飘逸的开叉裙摆，1 双带有银色花丝膝部和踝部装饰的黑色过膝战靴，以及 1 条包含大腿绑带的棕色腰带组合。领口和盔甲边缘饰有精致的银色纹饰，皮革质感细腻，金属高光处理考究，布料呈现出微风吹拂的动感。色调采用象牙白、炭黑、青铜色和银色，整体风格低调而高级。画面应呈现出高端日本 RPG 角色概念艺术的质感，细节丰富，姿态优雅，略带哥特风，全身人物独立呈现，无额外道具，无背景，仅在脚下有淡淡的柔和地面阴影。","imgs":["https://r2.qqsrc.com/images/originals/15331.jpg"]},{"i":8169,"text":"在一张纯浅灰色背景上绘制全身奇幻角色插画，采用精致的日系 RPG 概念艺术风格，线条清晰，渲染柔和，并呈现出逼真的皮革、毛皮和皮肤质感。描绘一位身材高大、体格健壮且皮肤白皙的年轻男性，以放松的重心转移姿势站立。他的右臂抬起横在额前，仿佛在遮挡光线，戴着手套的手触碰着深色帽檐；左臂自然下垂，拳头紧握。他的面部大部分被抬起的前臂和帽檐阴影遮挡，表情难以辨认。他留着 {argument name=\"hair color\" default=\"白金色\"} 的中长发，略显凌乱，在 {argument name=\"headwear\" default=\"黑色平顶帽\"} 下隐约可见，一侧耳朵戴着小耳环。为他穿上以深棕色、黑色和柔和红棕色为主的叠穿冒险家服装。上身穿着修身黑色短袖衬衫，外搭棕色皮质马甲，配有宽带和搭扣，颈部和肩部披着厚实的浅色毛领。锁骨处佩戴一条带有小型金属装饰的项链。双手戴着深色露指手套或修身皮手套，并佩戴多个层叠的腕带和护腕。腰间配有多条交叉的皮带、金属扣和悬挂饰品，臀部系着一条红棕色腰带，带有长长的垂坠布条。左侧腰间挂着 1 个小型皮袋。下身穿着修身深色长裤，大腿处系有带金属环和搭扣的绑带。脚蹬一双配套的深色高帮系带皮靴，配有加固的护膝或精致的金属护胫，略显风霜感但时尚感十足。从右侧腰间垂下一块长长的破损布片，末端带有微妙的装饰图案，并挂有 1 个金属吊坠或矛头状饰物。强调粗犷帅气的冒险家美学、精细的服装设计以及精致的游戏角色设定图质感，构图居中，全身从头到靴子完整可见，地面带有淡淡的柔和投影。","imgs":["https://r2.qqsrc.com/images/originals/15332.jpg"]},{"i":8170,"text":"一张华丽的日系浪漫喜剧电影海报，采用可爱又充满戏剧性的流行动漫吉祥物风格，设计如同电影预告海报。构图中心为一只全身卡通兔女郎吉祥物，名字为 {argument name=\"character name\" default=\"パン子\"}，她有着大大的白脸、黑色的身体、一只黑耳朵和一只亮红色的耳朵，轮廓线条粗犷，半闭的迷人双眼配有长睫毛，脸颊上有粉色腮红圆圈，小小的红鼻子，舌头微微探出，头顶戴着一个带有白色波点的粉色蝴蝶结。她穿着一件带有白色波点的无袖粉色连衣裙，颈部有黑色围巾状装饰，单手靠近脸颊，姿态自信且略带俏皮。背景是梦幻般的日落滨海城市天际线，水面有金色倒影，天空呈现粉、橙、蓝的柔和色调，伴有闪光、柔和的虚化效果，左侧有一座摩天轮。在中景处放置 2 个男性剪影，左侧一人站姿随意，右侧一人呈西装革履姿态，暗示潜在的恋爱对象。在边框周围添加茂盛的热带花卉和叶子，尤其是角落里的粉色木槿花，以及遍布画面的漂浮爱心和闪光效果。采用大胆、分层的日式海报布局，布满装饰性字体和贴纸。顶部用手写风格的日文写着：「笑って、泣いて、恋をして。アラサーの私、まだまだ諦めない！」并带有粉色强调和涂鸦心形线条。左上方包含一个明亮的粉色扇形徽章，写着「2026年 夏公開」。右侧放置垂直的日文文本：「私の幸せ、探しにいきます。」。左下方添加一个粉色丝带标签，写着「劇場版！」。底部中央创建醒目的主标题，采用粗体装饰性日文字体：「アラサー パン子の 婚活奮闘記」，配以粉色和深海军蓝文字、白色轮廓以及可爱的爱心装饰。下方添加一个粉色标语横幅，带有黄色高亮文字：「恋に迷って、人生はもっとキラキラする♥」。底部包含日式电影海报风格的小型伪造演职员表。在下方区域放置 4 张兔女郎角色的宝丽来风格小照片：左下 2 张，右下 2 张，每张展示不同的可爱场景，如特写姿势、坐在咖啡桌旁、戴着太阳镜或在户外摆拍。左下方添加一个标有“Today's Mission”并带有心形清单的笔记本页面，右下方放置一个带吸管的塑料冰饮杯和太阳镜。整体感觉：女性化、喜剧感、励志、闪耀、夸张且怀旧，就像一部由吉祥物女主主演的真人浪漫电影的恶搞海报。使用鲜艳的粉色、桃色日落色调、天蓝色、白色和海军蓝，并带有光泽高光和精致的宣传海报质感。","imgs":["https://r2.qqsrc.com/images/originals/15333.jpg"]},{"i":8171,"text":"一张简洁的企业编辑类信息图插画，用于关于制造业挑战的日本商业文章，背景设定在拥有金属加工机械的写实现代化工厂中，采用冷灰蓝色调。构图在模糊的工业车间背景上分为两个主题部分。在顶部中心，放置一个深海军蓝色的醒目日文大标题：{argument name=\"headline text\" default=\"製造業が直面する根深い課題: 「人手不足」と「技術伝承」\"}。在左侧前景中，展示 1 名身穿浅灰色制服和帽子、双臂交叉且神情担忧的工厂工人；附近添加一个圆形的白色图标，显示 6 个人的剪影，其中 3 个为深色实心，3 个为虚线轮廓，象征劳动力短缺。在右侧前景中，展示 2 名工厂工人在大型车床旁：1 名身穿海军蓝工作夹克和帽子、正在指点并演示机器操作的资深员工，以及 1 名身穿浅灰色制服和帽子、正在仔细观察的年轻员工。在他们附近，添加一个白色的气泡图标，内含一个海军蓝头部剪影，配有 2 个齿轮符号和 3 个写有“経験”、“勘”和“コツ”的小型日文气泡。在中心背景中，包含 2 名正在操作机器、略微失焦的额外工人，使工厂场景中总共可见 5 名工人。叠加两个带有深海军蓝色标题标签的圆角白色信息面板。左侧面板标题为“人手不足”，包含 3 个带有蓝色圆形勾选图标的要点：“若手人材の確保が困難”、“現場の負担増大”和“将来の生産性低下への懸念”。右侧面板标题为“技術伝承”，包含 3 个带有蓝色圆形勾选图标的要点：“熟練技術が属人化”、“暗黙知が言語化・標準化されていない”和“ベテランの退職による技術の断絶リスク”。在底部中心，放置一个深海军蓝色的圆角矩形标注框，内含白色日文文本：{argument name=\"callout text\" default=\"製造業の持続的な成長のために、これらの課題解決が急務\"}。添加 2 个指向底部标注框的大型白色箭头，分别来自左右两侧。整体风格仿照专业的咨询公司演示文稿或商业杂志插页：照片级的工人和机械、微妙的景深、高清晰度、平衡的布局、柔和的灯光、清晰的排版，以及专业的日本制造业信息图美学。","imgs":["https://r2.qqsrc.com/images/originals/15335.jpg"]},{"i":8172,"text":"一张简洁可爱的扁平矢量插画，主角是一位开朗的日本女学生，置于浅灰色纯色背景中心，画面展示从大腿中部以上的正面姿势。她留着长直的 {argument name=\"hair color\" default=\"black\"} 头发，配有侧分刘海，皮肤白皙，圆脸，双颊带有粉色腮红，一只眼睛睁开，另一只眼睛眨眼，小巧的鼻子，嘴巴微张露出笑容。她穿着经典的日本高中校服，包括深海军蓝西装外套、白色衬衫领、领口处系着大红色蝴蝶结，以及灰色百褶裙，外套上可见 2 枚金色纽扣。双臂向两侧水平伸出，面向观众，双手做出比耶手势，手指朝下。采用粗犷简洁的黑色轮廓线、柔和的淡色系扁平色彩、极简阴影、卡哇伊贴纸风格比例、对称构图以及友好俏皮的表情。","imgs":["https://r2.qqsrc.com/images/originals/15342.jpg"]},{"i":8173,"text":"一幅梦幻般的电影质感奇幻夜景，背景是深靛蓝色的星空，平静的海面如镜面般倒映着一切。左上方悬挂着 1 轮巨大的满月，银河斜向横跨整个背景。画面中央，一位身材修长的女子留着 {argument name=\"hair color\" default=\"黑色\"} 的长直发，赤脚走在浅浅的镜面水域上，从左向右行进，呈现出优雅的全身侧影。她身穿一件闪烁的半透明银色晚礼服，紧身胸衣闪闪发光，细肩带设计，裙摆轻盈飘逸，高开叉露出一条腿，裙摆在微风中摇曳。在她右侧，一道弯曲的魔法粒子弧线形成 1 条新月形轨迹，由发光的白玫瑰、花瓣和微小的光点组成，从她倒影附近的水面升起，并在她身旁向上盘旋。在她下方的水面上倒映着一个奇幻的镜像：1 只发光的透明白虎侧卧着，呈现出如液态光芒和星尘般的质感，带有明亮的条纹和柔和光亮的脸庞。水面如玻璃般平滑，带有细微的涟漪，清晰地倒映出女子、月亮、星星和魔法光芒。远处的地平线上坐落着低矮的深色岛屿。在底部中央，添加优雅的发光草书文字 {argument name=\"quote\" default=\"心有猛虎，细嗅蔷薇\"}。超精细、空灵、诗意、写实奇幻艺术，柔和月光，冷色调，高对比度，柔光效果，神秘氛围，宽银幕构图。","imgs":["https://r2.qqsrc.com/images/originals/15346.jpg"]},{"i":8174,"text":"一款极具视觉冲击力的动漫宣传访谈海报，设计为未来感现场音乐活动的精美杂志双页跨页。场景展示了一个座无虚席的夜间演唱会现场，观众挥舞着霓虹黄、蓝、紫色的荧光棒，背景是巨大的发光舞台、激光束、光斑、烟雾，以及一个巨大的三角形播放图标屏幕，上面写着“AI SUPERLIVE SUMMER 2026”。前景中央是两位动漫风格的女主持人，以戏剧性的侧后方视角呈现，两人都望向舞台。左侧角色为 {argument name=\"left character name\" default=\"ソラ\"}，身穿带有黑色和酸橙绿点缀的深色超大款连帽夹克，佩戴标有“06”的大型酸橙绿耳机，头顶举着一支亮黄色的荧光棒；她的脸部被一个矩形隐私遮挡块部分遮盖。右侧角色为 {argument name=\"right character name\" default=\"ナギ\"}，留着银白色短波波头，皮肤白皙，身穿浅色超大款连帽外套，在舞台灯光的柔和映照下，胸前握着一支蓝白色的发光指挥棒，侧脸表情动人，注视着演出。运用电影级的轮廓光、饱和度丰富的紫蓝色演唱会色调、反光织物高光，以及精致的动漫渲染，呈现出高级的编辑广告质感。排版仿照日本专题访谈风格，包含密集的文字覆盖、半透明深色面板、细霓虹黄边框以及醒目的无衬线字体。包含 8 个独特的文本块：左上角 1 个小型标题标签，写着“/ SPECIAL INTERVIEW /”；左上方 1 个大型日文标题，写着“この夏、AIと音楽の未来がステージで輝く！”；右上角 1 个活动 Logo 块，写着“AI SUPERLIVE SUMMER 2026”和“2026.7.18 SAT @ FUTURE ARENA ODAIBA”；左侧堆叠 3 个以“Q.”开头的黄色边框问答面板；右侧堆叠 3 个以“Q.”开头的黄色边框问答面板；以及人物附近标有“ソラ”和“ナギ”的 2 个角色介绍名称框。在底部左侧和中央添加一行醒目的日文结束语：“AIと音楽が響き合う、新しい夏がはじまる。 一緒に、未来を体験しよう！”。右下角包含一个重复活动名称和日期的页脚块，以及一个可见的二维码和标注官方网站的小字说明。整体风格融合了高端日本活动传单、访谈文章和主视觉图的特色，充满活力、未来感、情感张力与节日氛围。","imgs":["https://r2.qqsrc.com/images/originals/15347.jpg"]},{"i":8175,"text":"{\"type\":\"动漫美食漫画页\",\"style\":\"干净的类漫画数字插画，带有温暖的傍晚灯光、光泽感的美食渲染、细致的拉面店背景、柔和的粉彩角色配色，以及富有表现力的日式美食漫画风格\",\"format\":\"带有黑色边框的四格竖版漫画\",\"subject\":{\"main character\":{\"gender_presentation\":\"年轻女性\",\"age_appearance\":\"十几岁末至二十岁出头\",\"hair\":{\"color\":\"{argument name=\\\"hair color\\\" default=\\\"金黄色\\\"}\",\"style\":\"双马尾，发梢卷曲，直刘海\"},\"outfit\":\"浅灰色花卉纽扣开衫或针织上衣，黑色单肩包\",\"face_visibility\":\"在第 1 格和第 2 格中脸部被居中的矩形模糊遮挡，在第 3 格的 Q 版插图和第 4 格中完全可见\"},\"theme\":\"渴望并享受浓郁的家系拉面\"},\"layout\":{\"panel_count\":4,\"panels\":[{\"index\":1,\"scene\":\"傍晚时分城市街道上的拉面店外\",\"background_elements\":{\"count\":6,\"items\":[\"写有“家系”的大红灯笼\",\"写有“ラーメン”的红色店面暖帘\",\"写有“濃厚豚骨醤油ラーメン”并附带拉面照片的立式招牌\",\"玻璃店门入口\",\"有行人的城市傍晚街道\",\"带有竖排日语文本的对话气泡\"]},\"character_pose\":\"站在店前，一根手指靠近嘴唇，看起来很心动\",\"text\":{\"count\":4,\"items\":[\"家系\",\"ラーメン\",\"濃厚豚骨醤油ラーメン\",\"对话气泡写着“家系ラーメン抗えなくなる響き・・・”和“これは食べてくっきゃないでしょ！”\"]}},{\"index\":2,\"scene\":\"拉面店内的吧台\",\"background_elements\":{\"count\":10,\"items\":[\"水壶\",\"水杯\",\"筷筒\",\"红色调料罐\",\"小酱油瓶或调味瓶\",\"写有拉面价格的黑色项目\",\"竖排招牌“ライス無料”\",\"木制吧台\",\"椅子\",\"背景中模糊的墙面海报\"]},\"character_pose\":\"坐在吧台前，一只手拿着水杯喝水，另一只手拿着菜单\",\"text\":{\"count\":3,\"items\":[\"ライス無料\",\"菜单标题“ラーメン”\",\"对话文本“ライスいっちゃうか・・・”\"]}},{\"index\":3,\"scene\":\"拉面碗的特写镜头\",\"food\":{\"dish\":\"家系拉面\",\"components\":{\"count\":5,\"items\":[\"浓郁光亮的汤底\",\"中粗黄色面条\",\"4 片重叠的炖叉烧肉\",\"深绿色菠菜\",\"3 大片海苔\"]}},\"background\":\"带有闪光的放射状橙色背景\",\"extra_character\":\"右下角女孩的小型 Q 版头像，兴奋地微笑着\",\"text\":{\"count\":1,\"items\":[\"对话气泡“これこれ〜待ってました！”\"]}},{\"index\":4,\"scene\":\"女孩在桌前幸福地吃着拉面\",\"food_and_drink\":{\"count\":5,\"items\":[\"主拉面碗\",\"一碗白米饭\",\"一杯啤酒\",\"文字旁漂浮的海苔和叉烧装饰插画\",\"筷子挑起面条\"]},\"character_pose\":\"闭着眼睛一脸幸福，微笑着，脸颊微红，一只手用筷子挑起面条，另一只手扶着碗\",\"background\":\"带有闪光和花朵图案的柔和粉橙色渐变\",\"text\":{\"count\":2,\"items\":[\"大型竖排标语“今日はライスもつけてチートデイ！”\",\"对话气泡“DNAに素早く届く♥”\"]}}]},\"camera\":\"第 1 格中景，第 2 格室内中景，第 3 格极致美食特写，第 4 格用餐中景\",\"rendering_notes\":\"让拉面看起来格外诱人，叉烧肉要有光泽的油脂感，汤底要有丰富的质感，面条纹理要真实；保持漫画的可读性，使用地道的日式招牌和对话气泡；强调舒适的傍晚拉面店氛围和俏皮的放纵幽默感\"}","imgs":["https://r2.qqsrc.com/images/originals/15352.jpg"]},{"i":8176,"text":"一张梦幻般的柔和动漫电影海报插画，背景设定在一条布满繁密花卉马赛克墙绘的狭窄户外小巷中，画面呈现出闪烁的星光、柔和的雾气，以及薰衣草色、粉色、长春花色和奶油色的浪漫少女漫色彩分级。前景展示了一位可爱的少女，背影呈四分之三侧面，面部大部分被遮挡，留着银薰衣草色的短波波头，戴着装饰有小花的大号淡紫色蝴蝶结发饰。她穿着一件超大号的半透明淡紫色连帽衫，袖子上绣有花卉贴花，搭配层叠的柔和色调短裙，背着一个闪亮的淡紫色双肩包，包上挂满了挂件、丝带、毛绒球、徽章和星星装饰。她手里端着一个切开的蓝莓磅蛋糕，中心戏剧性地溢出了光泽感十足的深紫色蓝莓馅料，浓稠的糖浆流淌在蛋糕和盘子上。在蛋糕周围和前景下方散落着整颗蓝莓。尽管画面精美，但整体氛围要显得奇幻、精致且带有一丝喜剧色彩。将图像设计为日式电影海报，带有许多装饰性文字叠加和月桂叶装饰。在顶部，包含 3 行带有月桂花环的小型奖项说明。添加一个巨大的手写日文标题，采用粉色、白色和紫色的层叠字体，带有发光和贴纸般的轮廓，文字为：「冷凍したブルーベリー使ってパウンドケーキ焼いたら中身溢れて失敗した件。」（译：用冷冻蓝莓烤磅蛋糕结果内馅溢出失败了这件事。）在下方添加一行较小的副标题：「〜甘くて、ちょっぴり切ない青春のレシピ〜」（译：～甜蜜又略带苦涩的青春食谱～）。在右侧放置一个垂直的白色引语框，内含日文：「うまくいかない日だって、人生のスパイスになるんだ。」（译：即使是不顺利的日子，也是人生的调味品。）在左下角，添加一张别着的粉色便签，上面写着“Sweet but clumsy.”，以及一张手写的日文清单撕页。在蛋糕附近添加一个小小的对话气泡，写着“Oops!”。在右下角附近添加一个圆形的印章式封条，上面写着“Blueberry disaster”。在底部，添加白色的电影演职员表风格文字，包括“A FILM BY YUMEIRO PASTEL”，以及一行粉白相间的巨大上映日期：「{argument name=\"release date\" default=\"2024.6.30(SUN)\"} ROADSHOW」。在下方添加日文标语：「失敗は、最高の思い出になる。だから、また挑戦しよう。」（译：失败，会成为最棒的回忆。所以，让我们再次挑战吧。）用蕾丝、贴纸、纸屑和剪贴簿风格的装饰框住整张海报。画面要超精细、有光泽、感性、可爱、具有电影感，并刻意营造出一种关于烘焙失败的青春成长电影海报的夸张效果。","imgs":["https://r2.qqsrc.com/images/originals/15353.jpg"]},{"i":8177,"text":"一张 20 世纪 70 年代末的复古日本犯罪电影海报，采用日活（Nikkatsu）院线单张海报风格，纵向构图，背景为带有明显颗粒感、微弱污渍和墨迹褪色的米色旧纸张。主体图像是位于右上角和中心位置的 {argument name=\"lead actor name\" default=\"原田芳雄\"} 的大型忧郁半身肖像，他侧身背对镜头，留着浓密的深色卷发，表情严肃，身穿皱巴巴的浅灰色西装外套，内搭敞领白衬衫；面部大部分处于阴影中。背景是荒凉的工业码头，有起重机、低矮的工厂建筑和升入灰暗天空的浓重烟雾。在画面中下部，放置一个巨大的手写红色日文标题 {argument name=\"title text\" default=\"影の街\"}，以倾斜且强烈的笔触书写，部分覆盖了肖像和下方场景。在下半部分，添加第二个场景：黄昏或夜晚雨中的城市街道，路面湿润且带有倒影，左侧是一辆车顶红灯闪烁的深色警车，6 名身穿西装和风衣的男子正向前走，其中 1 名身穿米色风衣、领带松散的侦探形象走在队伍最前方。在最右侧，包含一列垂直排列的 5 张嵌入式演员肖像，每张都带有细边框，呈现出不同角色的深沉电影剧照。添加垂直日文排版：右上角为演员表“原田芳雄 主演”；左上角为两行标语“その男、刑事。 正義より、真実を追う。”；在主体图像右下角附近，添加另一段垂直宣传语“誰が敵で、誰が味方か。闇に消えた事件の中で、ただひとつの真実を掴むまで—”。底部包含横跨整个宽度的密集小字日文演职员表，右下角标注醒目的上映日期 {argument name=\"release date\" default=\"11.23\"}，下方印有“日活ロードショー”字样及小型制片厂标志。色调采用柔和的炭灰色、深褐色、烟雾蓝灰色和灰白色，红色标题是唯一的鲜艳色彩。整体氛围硬派、忧郁、粗粝且充满电影感，宛如一张失传的 1970 年代日本侦探电影海报。","imgs":["https://r2.qqsrc.com/images/originals/15354.jpg"]},{"i":8178,"text":"一幅超写实的未来城市景观，时间设定在 {argument name=\"year\" default=\"公元 100000 年\"}，视角从高处露台俯瞰，地面光洁如镜，左侧建筑上攀附着茂密的植被。前景中，3 个背对镜头的人物正眺望着这座城市：1 位身穿优雅米色长袍或斗篷的人类，1 位拥有外露机械细节的银色流线型安卓机器人，以及 1 位由闪烁光芒构成的神秘透明人形生物，宛如被折射能量勾勒出的隐形人。画面展现了一座宏伟的先进大都市，无数纤细的巨型建筑和针状塔楼从绿色的公园和水道中拔地而起，圆形高架平台支撑着花园与建筑，天际线上散布着多艘飞行器和悬浮结构。城市上方，一个巨大的透明环状或壳状轨道结构横跨天空，背景中悬挂着一颗巨大的苍白行星或卫星。温暖的黄金时刻阳光，大气薄雾，电影级尺度，高度精细的科幻建筑，乌托邦式又带有一丝诡谲的氛围，真实的材质，深远的景深，广角构图，展现出超越当今文明的史诗感，并特别强调了那个神秘的透明人形生物。","imgs":["https://r2.qqsrc.com/images/originals/15355.jpg"]},{"i":8179,"text":"一张明亮的日本电视综艺节目演播室截图，采用欢快的柔和色调偶像节目风格，构图为中景广角群像，展示了 {argument name=\"group size\" default=\"5\"} 位年轻女性紧密站在一起，中心表演者略微靠前，其他人围绕在她周围部分可见。她们的面部被柔和的矩形马赛克故意遮挡，如同社交媒体帖子的匿名处理，但她们的发型、服装、身体姿态和场景保持清晰。她们穿着协调的女性化舞台制服，色调为灰粉色和米色，领口带有白色蝴蝶结，肩部和胸部饰有花朵蕾丝，泡泡袖，金色纽扣，领口附近别着小型黑色领夹麦克风。中心女性留着齐肩浅棕色波波头，带有侧分刘海；后方和右侧两位较高的女性留着深棕色长卷发；左下角和右下角仅可见另外两名成员的头部。演播室背景色彩丰富且繁杂：米色和柔和色调的砖墙，左上角有风格化的树木剪裁，左侧是一个发光的紫色 LED 面板，周围环绕着装饰性的粉色华丽边框，并带有白色花朵图标，右侧是几何形状的柔和色调墙板。添加醒目的日语电视字幕，文字清晰易读。在左上角，放置一个黄黑相间的施工标志风格方框，带有斜向危险条纹，文字为“乃木坂工事中”，下方有较小的罗马字“nogizaka under construction”。在右上角，放置一个带有黄色危险条纹边框的黑色矩形，包含两行日语文本：“イントロ中のアドリブ曲紹介”和“ピッタリ歌い出しまで埋めろ!”。在下方中央，添加一个巨大的趣味标题，采用粗圆体日语字形，内容为 {argument name=\"main caption\" default=\"1つ この曲を\"}，颜色为亮黄色，带有橙色阴影、白色内边框、粗粉色轮廓，短语中融入了闪亮的星星装饰。整体构图应呈现出真实的电视广播暂停画面感，色彩丰富、精致且高度清晰，采用 16:9 宽高比，视觉重点在于底部的大号标题和中心表演者。","imgs":["https://r2.qqsrc.com/images/originals/15356.jpg"]},{"i":8180,"text":"一个灯光璀璨的日本电视综艺节目现场，两位年轻女性偶像并排站在一个小白色讲台后，采用腰部以上的半身中景构图。两人均身穿配套的浅灰色校服风格西装外套，配有银色纽扣、白色衬衫、灰色条纹丝带领结，左胸前别着协调的名牌，腰部可见精致的蕾丝细节。左侧女性留着深棕色至黑色的侧编发，垂在右肩上，双手在胸前交叠，身体略微向右倾斜。右侧女性留着长长的深色波浪卷发，垂在双肩，双手轻轻搭在讲台顶部。她们的面部被柔和的矩形模糊块遮挡。背景是色彩丰富且密集的电视演播室设计：左侧是一个高大的粉色闪光面板，上面布满了重复的白色图标，包括心形、三角形、雪花状花朵和树木剪影，并镶有华丽的金色饰边；中央是一个鲜艳的红橙色垂直面板，在主持人身后带有部分白色字母；右侧是一面黄色墙壁，装饰着金属几何图形，以及一个镶嵌着小型反光方块的大型弧形棕色马赛克拱门。包含 3 个可见的屏幕文字区域：左上角为日语节目 Logo，显示为 {argument name=\"show logo text\" default=\"日向坂で会いましょう\"}，采用俏皮的蓝白徽章样式；右上角为日语标题横幅，分两行显示 {argument name=\"headline text\" default=\"ガッツリ褒められ隊を攻略せよ！『褒め褒めストラックアウト』\"}，采用粗体白色文字配蓝色描边；左下角为一个带有红色边框的黑色告示牌，包含日语文本和一个大号分数 {argument name=\"score value\" default=\"9 pt\"}。左侧名牌显示 1 个日语成员姓名 {argument name=\"left name tag\" default=\"高瀬 愛奈\"}，右侧名牌显示 1 个日语成员姓名 {argument name=\"right name tag\" default=\"小坂 菜緒\"}。将其渲染为清晰的广播截图，呈现生动的演播室灯光、饱和的色彩、逼真的织物纹理、地道的日本电视图形以及精致的娱乐节目质感。","imgs":["https://r2.qqsrc.com/images/originals/15357.jpg"]},{"i":8181,"text":"{\"type\":\"日本电视综艺节目问答图形\",\"style\":\"现代日本广播截图，清晰的演播室灯光，高文本可读性，色彩丰富的游戏节目叠加层，半写实真人合成\",\"scene\":{\"setting\":\"偶像综艺节目演播室，带有粉色发光舞台元素，多名身着校服风格服装的女性参与者就座\",\"background\":\"青绿色图案全屏背景，图形布局后方带有微妙的花卉纹样\"},\"layout\":{\"format\":\"单帧广播画面，左侧为答案面板，右侧为主视频面板，右上角为标题横幅，底部为答案条\",\"sections\":[{\"title\":\"き わ べ ゆ う\",\"position\":\"左侧面板标题栏内左上方\",\"count\":5,\"labels\":[\"き\",\"わ\",\"べ\",\"ゆ\",\"う\"]},{\"title\":\"左侧线索列表\",\"position\":\"左侧垂直奶油色面板\",\"count\":4,\"labels\":[\"优雅的\",\"淘气的\",\"美女\",\"清爽的\"]},{\"title\":\"右上角横幅\",\"position\":\"右上角\",\"count\":2,\"labels\":[\"能说会道女王决定战!\",\"五十音图作文\"]},{\"title\":\"底部答案条\",\"position\":\"底部中右侧\",\"count\":2,\"labels\":[\"う\",\"不小心秃了\"]}],\"centerpiece\":\"右侧面板中央为一名就座的日本年轻女性的主摄像机镜头，周围是两侧及后方被裁剪的同样着装的女性\"},\"subjects\":{\"count\":5,\"primary subject\":{\"gender\":\"女性\",\"age\":\"十几岁到二十出头\",\"ethnicity\":\"日本\",\"hair\":\"长直黑发，中分\",\"outfit\":\"橄榄棕色校服西装外套，白色衬衫，条纹领带，胸前口袋有徽章，佩戴夹式领夹麦克风，可见写有“佐藤 爱樱”及假名注音的姓名牌\"},\"secondary subjects\":[\"左侧边缘的女性局部，留着长波浪黑发，身穿白色夹克\",\"右侧边缘的女性局部，留着长波浪黑发，身穿配套西装外套\",\"中央后方站立的女性，身穿配套西装外套和百褶裙\",\"后方左侧额外的被裁剪参与者\"]},\"graphics\":{\"left panel\":{\"background\":\"暖奶油色\",\"border\":\"粗黑边框，内侧有细线\",\"text\":\"大型加粗垂直黑色日文字符\"},\"top banner\":{\"shape\":\"多面洋红色渐变胶囊形状，带有光泽高光和白色轮廓，左侧有小型水晶状装饰元素\",\"sublabel\":\"右侧小型白色圆角矩形\"},\"bottom strip\":{\"background\":\"奶油色矩形面板，带有黑色边框\",\"icon\":\"左侧黑色六边形，内含大型黄色平假名“う”\",\"answer_text\":\"超大型加粗黑色书法日文字体\"}},\"camera\":{\"framing\":\"右侧面板内的中景镜头\",\"angle\":\"正对的广播摄像机角度\"},\"quality\":\"干净的高分辨率电视截图美学，具有精确的日文排版和地道的综艺节目构图\"}","imgs":["https://r2.qqsrc.com/images/originals/15358.jpg"]},{"i":8182,"text":"{\"type\":\"动漫喜剧漫画页\",\"subject\":\"来自宝可梦的伽勒尔呆呆王通过吃树果学习“打嗝”技能\",\"style\":{\"medium\":\"全彩漫画/插画\",\"franchise_inspiration\":\"宝可梦动画与游戏世界\",\"mood\":\"俏皮、幽默、略带荒诞\",\"rendering\":\"干净的赛璐珞动漫风格，表情生动，柔和的户外光影，细节丰富的树果和岩石河岸背景\"},\"characters\":[{\"name\":\"{argument name=\\\"pokemon name\\\" default=\\\"伽勒尔呆呆王\\\"}\",\"appearance\":\"圆润的紫色身体，白色腹部斑纹，巨大的螺旋壳紫色头部，带有绿色宝石和类似角的侧向突起，大部分时间坐在平坦的河岸岩石上\"},{\"name\":\"{argument name=\\\"trainer\\\" default=\\\"宝可梦训练家\\\"}\",\"appearance\":\"身穿深色夹克和红色装饰帽子的年轻男性训练家，肩挑着装满彩色树果的篮子\"}],\"setting\":{\"location\":\"阳光明媚的森林河岸，有浅溪、石头、树木和蓝天\",\"props\":[\"挑杆上挂着的 2 个装满树果的编织篮\",\"1 个写着“今日特训！打嗝”的木牌\",\"多堆彩色树果\",\"最后一格解释面板中 1 锅紫色汤\"]},\"layout\":{\"page_format\":\"单页漫画，共 6 格\",\"reading_order\":\"从左到右，从上到下\",\"sections\":[{\"title\":\"左上格\",\"position\":\"top-left\",\"count\":3,\"labels\":[\"训练家挑着 2 个树果篮到达\",\"对话框命令伽勒尔呆呆王今天必须学会打嗝，否则没晚饭吃\",\"伽勒尔呆呆王在水边放松，说水里感觉很舒服\"]},{\"title\":\"右上格\",\"position\":\"top-right\",\"count\":4,\"labels\":[\"训练家展示一篮树果\",\"对话框：把这些树果全吃掉，直到打出嗝来\",\"小字注：晚饭前不许找借口\",\"伽勒尔呆呆王说教道，每一颗树果都有自己的故事，应该细细品味\"]},{\"title\":\"中左格\",\"position\":\"middle-left\",\"count\":2,\"labels\":[\"旁白：数小时后……\",\"训练家不耐烦地询问为什么还没打出嗝\"]},{\"title\":\"中偏左格\",\"position\":\"middle-center-left\",\"count\":2,\"labels\":[\"伽勒尔呆呆王缓慢地咀嚼树果\",\"关于这颗树果有点酸的对话\"]},{\"title\":\"左下序列\",\"position\":\"bottom-left\",\"count\":6,\"labels\":[\"旁白：又过了数小时……\",\"训练家震惊于树果全吃光了却还没成功\",\"伽勒尔呆呆王回忆着阳光明媚的日子和丰富的自然风味\",\"训练家大喊快点用出打嗝\",\"伽勒尔呆呆王依然在缓慢咀嚼\",\"关于细嚼慢咽是好习惯但有时速度也很重要的小注脚\"]},{\"title\":\"右下高潮\",\"position\":\"bottom-right\",\"count\":4,\"labels\":[\"旁白：终于——\",\"巨大的风格化音效文字：嗝——！！\",\"训练家眼中闪烁着光芒，欢呼终于学会了技能\",\"方框解释：原因——因为它一口气喝光了晚饭的汤\"]}],\"text_language\":\"日语\"},\"composition\":{\"top_panels\":\"河边的对话与布置\",\"left lower sequence\":\"通过重复的咀嚼特写展现时间流逝的笑点\",\"bottom_right\":\"戏剧性的爆发式打嗝场景，伽勒尔呆呆王身后有紫色和绿色的能量爆发\"},\"effects\":{\"repeated_motifs\":\"缓慢咀嚼、训练家挫败感、树果随时间被消耗\",\"climax_fx\":\"紫色烟雾爆发、冲击线、超大号漫画字体、震惊的张大嘴巴\"},\"color_palette\":{\"dominant_colors\":[\"紫色\",\"绿色\",\"天蓝色\",\"大地棕\",\"树果红\",\"树果黄\"],\"contrast\":\"明亮欢快的户外色彩与强烈的戏剧性高潮效果形成对比\"},\"quality\":\"精致的社交媒体级漫画插画，方形格式\",\"prompt_note\":\"保持角色符合宝可梦的设计模型，强调幽默感源于准确的游戏逻辑：打嗝只有在吃过树果后才有效，但笑点在于宝可梦吃得太慢，只有在喝汤后才打出嗝。\"}","imgs":["https://r2.qqsrc.com/images/originals/15359.jpg"]},{"i":8183,"text":"{\"type\":\"日式电商产品广告\",\"product\":{\"category\":\"鞋类洗衣网袋\",\"name\":\"{argument name=\\\"product name\\\" default=\\\"靴用洗濯ネット\\\"}\",\"hero\":{\"bag\":{\"shape\":\"带有顶部网状面板和罗纹织物侧面的圆形翻盖拉链洗衣袋\",\"main colors\":[\"浅蓝色网面\",\"中灰色罗纹主体\",\"淡蓝色拉链饰边\"],\"position\":\"位于浅色木质桌面右前方\",\"state\":\"正面拉链打开，露出内部物品\"},\"contents\":{\"count\":2,\"item\":\"白色低帮运动鞋\",\"arrangement\":\"整洁的一双鞋并排放在袋内，鞋头朝前\"},\"background\":{\"setting\":\"明亮整洁的洗衣房\",\"main object\":\"右侧部分可见的滚筒洗衣机\",\"effects\":[\"产品后方有巨大的水花弧线\",\"画面中漂浮着水泡\"],\"lighting\":\"高调商业摄影布光，带有光泽高光和清晰阴影\"}}},\"layout\":{\"style\":\"紧凑的日式电商横幅构图，适用于在线市场主图\",\"sections\":[{\"title\":\"主标题区\",\"position\":\"左上角\",\"count\":3,\"labels\":[\"放入洗衣机即可！\",\"不伤鞋面\",\"彻底洗净！\"]},{\"title\":\"产品名称栏\",\"position\":\"标题下方居左\",\"count\":1,\"labels\":[\"靴用洗濯ネット\"]},{\"title\":\"功能图标\",\"position\":\"左侧垂直列\",\"count\":3,\"labels\":[\"直接放入洗衣机即可\",\"防止变形，轻柔洗涤\",\"彻底去除污垢和异味\"]},{\"title\":\"获奖徽章\",\"position\":\"右上角\",\"count\":1,\"labels\":[\"乐天排名\",\"No.1\",\"靴用洗濯ネット\",\"※日榜第 1 名 (2024 年 3 月 14 日更新)\"]},{\"title\":\"使用场景插图\",\"position\":\"左下角\",\"count\":1,\"labels\":[\"双手打开洗衣袋放入或展示内部鞋子\"]},{\"title\":\"颜色变体\",\"position\":\"底部居中\",\"count\":4,\"labels\":[\"灰色\",\"黄色\",\"蓝色\",\"浅灰色\"]},{\"title\":\"颜色数量标注\",\"position\":\"右下角\",\"count\":1,\"labels\":[\"可选\",\"4\",\"种颜色\"]}],\"color variants\":[{\"label\":\"灰色\",\"bag color\":\"灰色主体搭配浅蓝色网面\"},{\"label\":\"黄色\",\"bag color\":\"黄色主体搭配淡色饰边\"},{\"label\":\"蓝色\",\"bag color\":\"亮蓝色主体搭配淡色饰边\"},{\"label\":\"浅灰色\",\"bag color\":\"浅灰色主体搭配淡色饰边\"}]} ,\"typography\":{\"language\":\"日语\",\"headline treatment\":\"超大加粗无衬线字体，黑色与亮蓝色强调，动态换行\",\"accent colors\":[\"宝蓝色\",\"黄色\",\"白色\",\"红金色徽章装饰\",\"绿色和橙色功能图标\"]},\"composition notes\":\"制作一张精致且符合市场需求的日式销售图，产品置于中右侧，左侧放置大号利益点标题，右上角放置排名徽章，底部排列四个颜色选项缩略图。强调清洁、保护和洗涤力。使用光泽水花效果和气泡来暗示洗衣机性能。保持整体外观高端、值得信赖且具有高点击率。\",\"customization\":{\"headline emphasis color\":\"{argument name=\\\"accent color\\\" default=\\\"blue\\\"}\",\"bag main color\":\"{argument name=\\\"main bag color\\\" default=\\\"gray with light blue mesh\\\"}\",\"background appliance\":\"{argument name=\\\"background appliance\\\" default=\\\"front-loading washing machine\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/15363.jpg"]},{"i":8184,"text":"{\"type\":\"电影感照片拼贴\",\"subject\":{\"character\":\"亚洲青少年女学生音乐人\",\"outfit\":{\"top\":\"黑色校服西装外套，内搭白色衬衫，系着松散的黑色领带\",\"bottom\":\"深色百褶格纹裙\",\"legwear\":\"黑色及膝袜\",\"shoes\":\"黑色乐福鞋\"},\"hair\":{\"color\":\"深棕色至黑色\",\"style\":\"长直发带刘海，因潮湿和风吹略显凌乱\"},\"props\":[\"黑色电吉他\",\"自拍镜头中可见的智能手机\"],\"special_features\":[\"部分镜头中出现的小巧柔软天使翅膀\",\"忧郁内省的表情\"]},\"setting\":{\"location\":\"密集的香港城市街道和海滨\",\"time\":\"阴雨连绵的傍晚\",\"weather\":\"湿漉漉的地面，雾气弥漫，细雨蒙蒙\",\"background_elements\":[\"狭窄的城市街道\",\"高耸的公寓和商店建筑\",\"带有中文标识的霓虹灯和招牌\",\"双层巴士\",\"车流和车灯\",\"海滨天际线\"]},\"style\":{\"look\":\"智能手机快照写实感与电影记忆影像色调的结合\",\"color\":\"柔和的青色、棕色、灰色和琥珀色调，色彩略显褪色\",\"lighting\":\"自然阴天光线，昏暗的城市微光，湿润表面的反光\",\"camera\":\"随意的手机手持摄影，不完美的构图，轻微的运动模糊，浅至中等景深\",\"mood\":\"怀旧、忧郁、都市青春音乐视频插曲\"},\"layout\":{\"format\":\"圆角 12 张照片拼贴，采用 3 列 4 行网格布局\",\"count\":12,\"sections\":[{\"title\":\"第一行\",\"position\":\"row 1\",\"count\":3,\"labels\":[\"带有电车轨道和高楼的雨中香港十字路口\",\"透过电车或列车窗户看到的女孩，带有倒影和运动模糊\",\"女孩在室内的镜面自拍，背着吉他并佩戴着柔软的天使翅膀\"]},{\"title\":\"第二行\",\"position\":\"row 2\",\"count\":3,\"labels\":[\"湿润街道标志上她的腿部和乐福鞋特写\",\"天台或高处俯瞰城市视角，她的头发位于画面边缘，背景是朦胧的天际线\",\"弹奏黑色电吉他的手部特写\"]},{\"title\":\"第三行\",\"position\":\"row 3\",\"count\":3,\"labels\":[\"夜晚站在便利店或自动售货冷柜前的女孩\",\"咖啡桌上的杯碟、智能手机和小型金属糖罐\",\"海港水面与远方天际线，她的头发拂过画面\"]},{\"title\":\"第四行\",\"position\":\"row 4\",\"count\":3,\"labels\":[\"雨中街道上女孩背着吉他的全身照，隐约可见翅膀\",\"透过布满雨水的窗户或玻璃板拍摄的肖像，带有冷凝水珠\",\"湿润的城市街道，远处有一个孤独的身影和模糊的交通信号灯\"]}],\"centerpiece\":\"反复出现的学生吉他手形象，仿佛记录了在香港雨中的一天\"},\"prompt\":\"创建一个 12 张图片的拼贴画，感觉就像 {argument name=\\\"character name\\\" default=\\\"一位未具名的学生吉他手\\\"} 在漫步 {argument name=\\\"city\\\" default=\\\"香港\\\"} 时用智能手机随意拍摄的瞬间。拼贴画应看起来像亲密的、偶然的快照和记忆碎片，而不是精修的商业摄影。包含 12 张图片，采用圆角 3x4 网格，每帧的构图和距离略有不同，展示雨中街道、交通倒影、带有黑色电吉他的镜面自拍、鞋子特写、弹吉他的手、咖啡桌细节、便利店玻璃、海港天际线和雨水浸润的城市夜景。女孩穿着 {argument name=\\\"outfit style\\\" default=\\\"黑色校服西装外套、白衬衫、黑领带、格纹裙、及膝袜和乐福鞋\\\"}，留着 {argument name=\\\"hair style\\\" default=\\\"长发带刘海\\\"}。仅在部分画面中添加微妙的 {argument name=\\\"fantasy element\\\" default=\\\"天使翅膀\\\"}，将梦幻感融入现实。强调手持手机的不完美感、轻微模糊、反光、偏心构图、潮湿的氛围、柔和的电影级调色，以及那种可以插入音乐视频插曲的场景感。\"}","imgs":["https://r2.qqsrc.com/images/originals/15365.jpg"]},{"i":8185,"text":"一张充满活力的动漫风格 YouTube 直播游戏封面图，采用 16:9 宽屏构图，背景为霓虹紫粉色调的主播房间。画面中心是一位可爱的猫娘 VTuber，她坐在书桌前，半身出镜，身体前倾，充满活力，一只手握着鼠标，另一只手向观众伸出。她留着 {argument name=\"hair color\" default=\"浅橘金色\"} 的波波头，配有柔和的刘海、毛茸茸的棕奶油色猫耳，身后可见猫尾。她的面部被画面中央的一个实心矩形遮挡块刻意遮盖。她穿着黑白配色的女仆装，包括荷叶边白衬衫、黑色连衣裙身、泡泡袖、白色褶边、黑色丝带蝴蝶结以及金色铃铛颈圈。书桌上放置着带有明亮 RGB 灯效的机械键盘、发光的电竞鼠标，最左侧放置着带有粉紫色 LED 灯光的直播麦克风。前景放置 2 个猫咪主题的桌面摆件：左下角是一个猫脸毛绒玩具，右下角是一个黑猫造型的马克杯。她身后是一把带有爪印细节的电竞椅。在左侧，添加醒目的粗体韩文标题，采用厚实的白色块状字体，配有黑色填充阴影和发光的紫色轮廓，分 2 行排列：{argument name=\"headline text\" default=\"방송중 대참사\"}。下方添加一个较小的黄色漫画风格爆炸气泡字幕，黑色轮廓，文字为 {argument name=\"sub text\" default=\"> 크리퍼 실화냐\"}。在右侧，展示 1 台向内倾斜的大型电脑显示器，屏幕显示着类似 Minecraft 的场景，包括明亮的蓝天、绿树、水面，以及一个巨大的绿色苦力怕向观众扑来，边缘经过戏剧性的贴纸式剪裁处理。在显示器周围添加星爆效果和霓虹装饰，以增强混乱感。采用夸张的封面美学：超饱和色彩、锐利的赛璐珞阴影、粗轮廓、光泽高光、高对比度、动态视角，营造出令人忍不住点击的直播事故氛围。","imgs":["https://r2.qqsrc.com/images/originals/15366.jpg"]},{"i":8186,"text":"{\"type\":\"8 格浪漫漫画页\",\"style\":\"干净精致的动漫漫画插图，柔和的室内光线，温暖中性的客厅色调，细腻的角色渲染，现代数字漫画排版\",\"title_text\":{\"main\":\"恋するメイドロボと、気付かないマスター\",\"subtitle\":\"第４話　それは、近すぎます\"},\"page\":{\"background\":\"带有 2 列 4 行边框漫画格的白色页面\",\"panel_count\":8},\"characters\":{\"female_1\":{\"role\":\"女仆机器人\",\"appearance\":\"娇小的年轻女性，留着极长的银白色头发，直刘海，发尾微卷，戴着白色女仆发带，穿着黑白经典女仆装配荷叶边围裙，领口有黑色丝带，双耳附近有金属质感的耳罩式机器人配件，肤色苍白，紫罗兰色大眼睛，神态害羞\"},\"male_1\":{\"role\":\"主人\",\"appearance\":\"年轻男性，留着凌乱的深棕色短发，身材高大宽阔，穿着深炭灰色开领衬衫，表情冷静但迟钝\"}},\"setting\":\"舒适的客厅，配有沙发、书架、相框、台灯和柔和的傍晚室内光线\",\"layout\":{\"sections\":[{\"title\":\"1\",\"position\":\"左上\",\"count\":1,\"labels\":[\"对与主人距离的耐受力下降……\"]},{\"title\":\"2\",\"position\":\"右上\",\"count\":1,\"labels\":[\"在看什么呢？\"]},{\"title\":\"3\",\"position\":\"中左上\",\"count\":1,\"labels\":[\"……！\"]},{\"title\":\"4\",\"position\":\"中右上\",\"count\":1,\"labels\":[\"这书挺难的\"]},{\"title\":\"5\",\"position\":\"中左下\",\"count\":1,\"labels\":[\"这里看得懂吗？\"]},{\"title\":\"6\",\"position\":\"中右下\",\"count\":1,\"labels\":[\"看不懂的话我教你\"]},{\"title\":\"7\",\"position\":\"左下\",\"count\":1,\"labels\":[\"别太勉强了\"]},{\"title\":\"8\",\"position\":\"右下\",\"count\":1,\"labels\":[\"原因：主人\"]}],\"reading_order\":\"从左到右，从上到下\"},\"panel_descriptions\":[{\"panel\":1,\"scene\":\"女仆机器人独自坐在沙发上，双手捧着一本深色精装书阅读。左侧出现一个竖排旁白框。她看起来沉稳但娇柔。\"},{\"panel\":2,\"scene\":\"主人从右侧凑过肩膀看向书本。女仆机器人微微垂下目光。右侧的对话气泡显示他在询问她在看什么。\"},{\"panel\":3,\"scene\":\"他靠得更近了，两人的脸贴得很近，一起看着打开的书。女仆机器人惊讶地僵住了。左侧的一个小对话气泡显示出她受惊的反应。\"},{\"panel\":4,\"scene\":\"两人几乎肩并肩，一起看着书。主人语气随意地说这是一本很难的书。\"},{\"panel\":5,\"scene\":\"主人凑得很近，用手指着打开书页的某处。女仆机器人依然僵硬且慌乱。对话气泡询问她是否理解这一部分。\"},{\"panel\":6,\"scene\":\"双人近景。女仆机器人转头看向他，脸颊泛起明显的红晕，紫罗兰色的大眼睛睁大，带着害羞的紧张感。他继续从右侧以支持的语气说话。\"},{\"panel\":7,\"scene\":\"主人退后一步，独自站在房间里，温柔地说话。背景家具变得更加清晰。左侧的对话气泡说不要勉强自己。\"},{\"panel\":8,\"scene\":\"女仆机器人单人特写，双手捂在嘴前，脸庞极度慌乱，头发散落在肩头。她身旁重复出现粉色的手写拟声词，表现出心跳加速，竖排旁白框说明原因是主人。\"}],\"composition_notes\":\"除第 7 格外，保持女仆机器人作为每一格的情感中心。强调从第 2 格到第 6 格逐渐拉近的身体距离。保留漫画对话气泡、旁白框以及黑色方块中的 1 到 8 格编号。基调为带有纯真紧张感的浪漫喜剧，非成人向。\"}","imgs":["https://r2.qqsrc.com/images/originals/15369.jpg"]},{"i":8187,"text":"{\"type\":\"动画漫画页面\",\"style\":\"柔和阴影浪漫喜剧漫画，精致数字插画，温暖室内光效，干净的分镜边框，细腻的角色渲染，轻小说美学\",\"format\":\"单页 8 格，采用 2 列 4 行布局\",\"page\":{\"title_top\":\"恋するメイドロボと、気付かないマスター\",\"subtitle\":\"第5话　それは、意識してしまいます\"},\"setting\":{\"location\":\"连接厨房的温馨现代客厅\",\"details\":[\"沙发\",\"书架\",\"墙上挂画\",\"盆栽\",\"厨房台面\",\"吊灯\",\"暖米色与棕色调室内装潢\"]},\"characters\":[{\"role\":\"女仆机器人\",\"gender\":\"女性\",\"appearance\":{\"age\":\"年轻动画少女\",\"hair\":{\"color\":\"{argument name=\\\"hair color\\\" default=\\\"银色\\\"}\",\"style\":\"超长直发配柔和波浪，齐刘海，两侧带有黑色丝带蝴蝶结\"},\"eyes\":\"紫蓝色\",\"outfit\":[\"黑白经典女仆装\",\"白色荷叶边围裙\",\"白色蕾丝女仆发带\",\"领口黑色蝴蝶结\",\"长袖配白色荷叶边袖口\"]},\"expression_arc\":[\"惊慌的内部故障\",\"慌乱的接受\",\"接过咖啡时的紧张\",\"害羞导致的热量积聚\",\"无法专心阅读\",\"在主人身边深深脸红\"]},{\"role\":\"主人\",\"gender\":\"男性\",\"appearance\":{\"age\":\"年轻男性\",\"hair\":\"深棕色短碎发\",\"outfit\":[\"深炭灰色衬衫，袖口卷起\",\"深色长裤\",\"黑色皮带\"]},\"demeanor\":\"随和、善良、迟钝\"}],\"layout\":{\"sections\":[{\"title\":\"1\",\"position\":\"左上\",\"count\":1,\"labels\":[\"女仆机器人坐在沙发上，一只手放在胸口，垂直旁白框写着 内部異常…継続中\"]},{\"title\":\"2\",\"position\":\"右上\",\"count\":1,\"labels\":[\"主人站在厨房拿着白色马克杯，对话气泡写着 おーい、コーヒー淹れたぞ\"]},{\"title\":\"3\",\"position\":\"中左上\",\"count\":1,\"labels\":[\"女仆转身露出惊讶的红晕，对话气泡写着 は、はいっ…！\"]},{\"title\":\"4\",\"position\":\"中右上\",\"count\":1,\"labels\":[\"交换咖啡杯的手部特写，小对话气泡写着 ……っ\"]},{\"title\":\"5\",\"position\":\"中左下\",\"count\":1,\"labels\":[\"女仆将热马克杯贴近胸口，垂直旁白框写着 接触時、異常な熱量を確認\"]},{\"title\":\"6\",\"position\":\"中右下\",\"count\":1,\"labels\":[\"主人坐在沙发上靠近女仆，两人半身可见，对话气泡写着 さっきの本、続き読むのか？\"]},{\"title\":\"7\",\"position\":\"左下\",\"count\":1,\"labels\":[\"女仆拿着打开的书脸红不已，对话气泡写着 ……読めません\"]},{\"title\":\"8\",\"position\":\"右下\",\"count\":1,\"labels\":[\"主人凑近表现出关切，女仆脸红并拿着咖啡，对话气泡写着 顔、赤いぞ。大丈夫か？ 和 原因：マスターです…\"]}],\"count\":8},\"composition\":{\"camera\":\"中景与特写交替\",\"mood\":\"甜蜜、尴尬、浪漫张力、喜剧式害羞\",\"color_palette\":\"柔和的暖棕色、奶油色、黑色、白色以及柔和的银色发色\",\"focus\":\"女仆机器人因与迟钝主人的单纯互动而变得慌乱并过热\"}}","imgs":["https://r2.qqsrc.com/images/originals/15370.jpg"]},{"i":8188,"text":"{\"type\":\"单页动漫漫画\",\"format\":\"垂直 8 分镜漫画页，2 列 4 行\",\"style\":\"柔和渲染的现代动漫插画，带有清晰的漫画分镜边框，温暖的室内光线，电影般的居家浪漫氛围，精致的衣物褶边，细腻的脸红效果，轻柔的喜剧剧情基调\",\"page\":{\"background\":\"白色页面，带有细黑色分镜边框\",\"title_top\":\"恋するメイドロボと、気付かないマスター\",\"subtitle_top\":\"第 6 话　それは、気のせいじゃない\"},\"setting\":{\"location\":\"舒适的现代公寓室内\",\"areas\":[\"带吧台的厨房，碗、打蛋器、食材、玻璃杯和温暖的吸顶灯\",\"带沙发、墙面装饰画、置物架和盆栽的客厅\"],\"time\":\"傍晚\"},\"characters\":{\"count\":2,\"primary\":{\"description\":\"美丽的机器人女仆，外表为青少年至年轻成年人，极长的银色长发带有柔和的淡紫色调，齐刘海，两侧有黑色丝带蝴蝶结，皮肤白皙，大大的紫罗兰色眼睛，穿着经典的黑白女仆装，配有白色褶边发带、白色围裙、泡泡袖、蕾丝袖口和领口的黑色蝴蝶结\",\"emotion_arc\":[\"专注但精力不足\",\"因近距离接触而受惊\",\"慌乱且说不出话\",\"深感尴尬且坠入爱河\"]},\"secondary\":{\"description\":\"迟钝的主人，年轻男性，留着凌乱的黑色短发，面部干净无胡茬，穿着深炭灰色衬衫，袖子随意卷起，神情冷静且略带关切\"}},\"layout\":{\"sections\":[{\"title\":\"1\",\"position\":\"左上\",\"count\":1,\"labels\":[\"女仆机器人在厨房用打蛋器搅拌金属碗里的面糊，台面上放着食材，垂直标题框写着 動作精度、低下中…\"]},{\"title\":\"2\",\"position\":\"右上\",\"count\":1,\"labels\":[\"主人站在她身后，在她举起玻璃杯时扶住她，对话框写着 危ない\"]},{\"title\":\"3\",\"position\":\"中左\",\"count\":1,\"labels\":[\"女仆脸红的特写镜头，主人靠近她的脸，对话框写着 ……っ\"]},{\"title\":\"4\",\"position\":\"中右\",\"count\":1,\"labels\":[\"主人独自在客厅，手托下巴，神情困惑，对话框写着 最近、様子おかしくないか？\"]},{\"title\":\"5\",\"position\":\"中下左\",\"count\":1,\"labels\":[\"女仆坐在沙发上，低着头，紧抓胸口，脸红，对话框写着 問題　ありません\"]},{\"title\":\"6\",\"position\":\"中下右\",\"count\":1,\"labels\":[\"主人靠在沙发上交叉双臂，依然半信半疑，对话框写着 そうか…？\"]},{\"title\":\"7\",\"position\":\"左下\",\"count\":1,\"labels\":[\"女仆双手紧张地摆弄膝盖上的围裙布料的特写，垂直标题框写着 原因特定済み\"]},{\"title\":\"8\",\"position\":\"右下\",\"count\":1,\"labels\":[\"女仆坐在沙发上的正面视角，手按胸口，无法告白，对话框写着 ……言えません\"]}],\"centerpiece\":\"坠入爱河的女仆机器人与完全迟钝的主人之间的情感反差\"},\"visual_direction\":{\"camera\":\"多样的漫画构图，包括中景、特写和手部细节插入\",\"color_palette\":\"温暖的米色、奶油色、柔和的棕色室内色调，与黑白女仆装及冷色调的银紫色头发形成对比\",\"expression_focus\":\"强烈的脸红、害羞的眼神、迟疑的嘴唇、男性关切的表情\",\"rendering_notes\":\"高细节发丝、精致褶边、光泽感眼睛、背景柔和的景深，精美的网漫质量分镜艺术\"}}","imgs":["https://r2.qqsrc.com/images/originals/15371.jpg"]},{"i":8189,"text":"{\"type\":\"8 格动漫浪漫漫画页面\",\"style\":\"柔和的青年漫画风格全彩插画，温暖的室内光线，干净的黑色分镜框，现代数字动漫渲染，充满浪漫情感张力，强调细微的脸红和肢体语言\",\"page\":{\"background\":\"白色页面，配有 2 列 4 行的黑色边框分镜格\",\"panel_count\":8,\"numbered_panels\":true,\"panel_numbers\":[1,2,3,4,5,6,7,8],\"title_area\":{\"top_header\":\"恋するメイドロボと、気付かないマスター\",\"subtitle\":\"第7话　それは、勘違いじゃない\"}},\"setting\":{\"location\":\"温馨的客厅\",\"details\":[\"布艺沙发\",\"带有透明窗帘的大型阳光窗户\",\"小型盆栽\",\"墙上的相框\",\"温暖的米棕色内饰\"]},\"characters\":[{\"role\":\"master\",\"appearance\":\"年轻男性，凌乱的深棕色至黑色头发，穿着深炭灰色衬衫，袖子随意卷起，坐在沙发上，神情严肃而深思\"},{\"role\":\"maid robot\",\"appearance\":\"年轻动漫少女，极长的银紫色头发，皮肤白皙，黑色丝带发饰，经典的黑白女仆装配荷叶边白围裙，蕾丝女仆头饰，领口有黑色蝴蝶结，神情害羞且慌乱\"}],\"layout\":{\"sections\":[{\"title\":\"1\",\"position\":\"左上\",\"count\":1,\"labels\":[\"主人坐在沙发上，手托下巴，内心独白\"]},{\"title\":\"2\",\"position\":\"右上\",\"count\":1,\"labels\":[\"机器人女仆端着托盘和杯子站立，递上饮料\"]},{\"title\":\"3\",\"position\":\"中上左\",\"count\":1,\"labels\":[\"越肩构图，两人面对面，安静的停顿\"]},{\"title\":\"4\",\"position\":\"中上右\",\"count\":1,\"labels\":[\"女仆特写，拿着杯子受惊的反应\"]},{\"title\":\"5\",\"position\":\"中下左\",\"count\":1,\"labels\":[\"主人特写，直接询问，关切的表情\"]},{\"title\":\"6\",\"position\":\"中下右\",\"count\":1,\"labels\":[\"女仆沉默僵住，明显颤抖\"]},{\"title\":\"7\",\"position\":\"左下\",\"count\":1,\"labels\":[\"主人温柔地说话，安抚的语气\"]},{\"title\":\"8\",\"position\":\"右下\",\"count\":1,\"labels\":[\"女仆低头，脸红心跳，双手捧着马克杯\"]}],\"speech_balloons\":{\"count\":8,\"texts\":[\"最近、あいつ…明らかに変だな\",\"お飲み物を…\",\"……なぁ\",\"は、はい…！\",\"俺に、何か隠してるだろ？\",\"……っ\",\"無理に言わなくていいけどさ\",\"隠しているのは…\"]}},\"panel_descriptions\":[{\"panel\":1,\"composition\":\"中景，主人坐在沙发左侧，身体前倾，手肘撑在膝盖上，手指靠近嘴边，表情困扰\",\"emotion\":\"怀疑与关切\"},{\"panel\":2,\"composition\":\"全景至七分景，机器人女仆站在室内，拿着小圆托盘和杯子，身体微微转向主人\",\"emotion\":\"正式但紧张\"},{\"panel\":3,\"composition\":\"紧凑的对话分镜，左前景为女仆背影，主人在沙发上正对着她\",\"emotion\":\"犹豫\"},{\"panel\":4,\"composition\":\"女仆正面特写，肩膀紧绷，头部周围有细小的动作线，表现出惊慌\",\"emotion\":\"受惊与尴尬\"},{\"panel\":5,\"composition\":\"主人特写，姿态坚定但不具攻击性，提出严肃的问题\",\"emotion\":\"温柔的质问\"},{\"panel\":6,\"composition\":\"女仆特写，紧紧抓住杯子，身体周围有轻微的颤抖线\",\"emotion\":\"无言的焦虑\"},{\"panel\":7,\"composition\":\"中近景，主人表情柔和，正在安抚她\",\"emotion\":\"仁慈与耐心\"},{\"panel\":8,\"composition\":\"女仆特写，低着头，脸颊深红，双手紧握马克杯，长发垂落\",\"emotion\":\"浪漫的尴尬与隐藏的情感\"}],\"color_palette\":{\"primary\":[\"暖米色\",\"柔棕色\",\"炭灰色\",\"黑色\",\"白色\",\"银紫色\"],\"accents\":[\"柔粉色脸红\",\"柔和的金色窗光\"]},\"quality\":\"高质量漫画页面，适合社交媒体发布，日语文字清晰可读，电影感分镜表达生动\"}","imgs":["https://r2.qqsrc.com/images/originals/15372.jpg"]},{"i":8190,"text":"创作一张日式美少女游戏宣传海报，风格参考高端视觉小说包装封面与商店页面合成图。画面分为三个垂直区域。左侧三分之二为日落时分的戏剧性插画主视觉：梦幻般的春日天空，布满粉色与紫色的云彩，带有发光的边缘光，飘落的花瓣，以及倒映着光影的湿润路面或河畔小径。画面中展示 4 位身穿校服的动漫少女，她们都带有柔和的情感表达，发丝在风中飘动，细节极其丰富。最显眼的主角位于左上方，以胸部以上侧面或四分之三侧面呈现，留着长长的深色头发，佩戴小型花朵发饰，神情忧郁。第二位少女位于左下方，留着浅银色长发，佩戴丝带配饰，身体略微背向。第三位少女位于画面下方中央，体型较小，留着紫红色或红棕色头发，姿态低垂，略显忧伤。第四位少女位于右中部，金色或浅棕色头发，仰望天空，表情充满希望。在主视觉图的最底部中央，展示 2 个微小的全身剪影，男孩和女孩在发光的远方牵手，倒映在湿润的地面上。在左上方添加一片白色的羽毛，并在画面中散布樱花花瓣。在左下方至中央位置叠加优雅的日文标题排版，使用白色大号毛笔风格衬线字体：「{argument name=\"title text\" default=\"さよならの向こう側で\"}」，下方配有一行较小的副标题。在最左侧边缘，垂直排列 3 行白色的小号日文宣传标语。在左下角，添加 2 个堆叠的黑色产品标签，配以白色文字，类似于 PC 游戏包装徽章，一个写着 Windows 兼容，另一个写着全年龄适用。\n\n中间是一个狭窄的深靛蓝色垂直带，将艺术图与信息面板隔开。在此带上，再次垂直放置大号白色日文游戏标题，下方配有较小的垂直标语。保持此区域简洁优雅，如同游戏盒的侧脊。\n\n右侧三分之一是一个柔和的奶油色信息面板，带有细腻的纸张质感。在此面板的左上方，添加一个括号内的加粗日文标题：「【あらすじ】」，随后是几行日文剧情简介，排版如同视觉小说描述页面。下方添加一条虚线分割线。接着添加第二个括号标题：「【特徴】」，包含 4 个功能要点，每个要点前配有一个简单的图标。这 4 个功能分别是：分支选择、全程语音支持、催人泪下的情感故事以及大量精美 CG。使用深蓝灰色的小图标和文字。添加另一条分割线，然后是第三个括号标题：「【プレイヤーへ】」，后接 2 行简短的日文寄语。\n\n在奶油色面板的最右侧，垂直堆叠 4 个圆角矩形截图缩略图，每个缩略图带有细白边框。缩略图 1：深发女主角在日落时分的海边栏杆旁。缩略图 2：浅发女主角在蔚蓝大海背景下，发丝随风飘动。缩略图 3：少女在室内，身处阳光明媚的教室或咖啡馆窗边，神情温暖而沉思。缩略图 4：少女被樱花环绕，沐浴在柔和的粉色光芒中。在奶油色面板底部，放置一个宽大的圆角薰衣草色功能栏，包含 4 个大图标，下方或侧面配有简短的日文标签：一本打开的书、一个麦克风、一个图像/照片符号以及一个分支路径/分享类图标。整体氛围应充满怀旧、浪漫、电影感，且情感充沛，如同 2000 年代至 2010 年代高预算日式美少女游戏广告。使用精致的动漫插画、发光的背光效果、浓郁的粉彩日落色调、光泽反射、精美的排版以及地道的视觉小说宣传设计。","imgs":["https://r2.qqsrc.com/images/originals/15373.jpg"]},{"i":8191,"text":"{\"type\":\"动漫动作游戏项目表\",\"style\":\"高端日本动作 RPG 电影感项目，精致的 3D 动漫渲染，戏剧性的蓝色夜间照明，发光的剑刃特效，樱花花瓣，动态模糊，奇幻武士氛围\",\"subject\":{\"character\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"シャルロット\\\"}\",\"gender_presentation\":\"年轻女性\",\"hair\":{\"color\":\"{argument name=\\\"hair color\\\" default=\\\"银白色\\\"}\",\"style\":\"非常长的直发，带有柔和的刘海，一侧有花朵发饰\"},\"outfit\":{\"primary_color\":\"深靛蓝色\",\"description\":\"优雅的仿和服战斗服，带有长长的飘逸袖子、分层裙摆、腰封式腰带，面料上有白色花朵和金色细节图案\"},\"weapon\":\"带有发光蓝色刀刃的武士刀\"},\"enemies\":{\"count\":8,\"description\":\"包围在庭院中的黑衣忍者剑客\"}},\"environment\":{\"location\":\"夜晚的传统日本寺庙庭院\",\"details\":[\"石板路\",\"木制神殿建筑\",\"温暖的纸灯笼\",\"樱花树\",\"飘落的花瓣\",\"深蓝色天空\"]},\"ui\":{\"components\":[\"左上角的角色状态栏\",\"右上角的圆形小地图\",\"下角的技能图标\",\"右侧的连击计数文本\",\"部分面板中的字幕或招式文本\"]},\"layout\":{\"grid\":{\"rows\":3,\"columns\":3,\"count\":9},\"numbered_panels\":true,\"sections\":[{\"title\":\"1\",\"position\":\"左上\",\"count\":1,\"description\":\"宽视角游戏画面，女主角站在寺庙庭院中央，8 名忍者敌人环绕着她；可见游戏 HUD；底部有对话文本；连击计数为 0\"},{\"title\":\"2\",\"position\":\"中上\",\"count\":1,\"description\":\"女主角在胸前拔出或紧握发光武士刀的特写，刀刃周围有蓝色火花状粒子，自信的攻击前姿势；连击计数为 0\"},{\"title\":\"3\",\"position\":\"右上\",\"count\":1,\"description\":\"快速旋转的横向斩击，明亮的圆形蓝色能量环从剑中扩散并击退敌人；连击计数为 12\"},{\"title\":\"4\",\"position\":\"左中\",\"count\":1,\"description\":\"动态空中跳跃，全身侧视图，长袍和长发飘动，剑刃划出一道扫过的蓝色弧线；连击计数为 25\"},{\"title\":\"5\",\"position\":\"正中\",\"count\":1,\"description\":\"俯视动作镜头，她向下俯冲，剑尖朝下，袖子像翅膀一样展开，下方是敌人；连击计数为 25\"},{\"title\":\"6\",\"position\":\"右中\",\"count\":1,\"description\":\"冲击帧，她落地并从地面释放出巨大的蓝色能量爆发，敌人被冲击波震开；连击计数为 58\"},{\"title\":\"7\",\"position\":\"左下\",\"count\":1,\"description\":\"特殊招式标题卡，深蓝色背景，带有发光的剑环；巨大的日文文本包括角色名称和攻击标题；连击计数为 128\",\"visible_text\":[\"シャルロット夢想！\",\"一瞬十撃・花月ノ太刀\",\"128 Combo\"]},{\"title\":\"8\",\"position\":\"中下\",\"count\":1,\"description\":\"后方四分之三视角游戏画面，女主角在庭院中完成了一次巨大的圆形扫斩，长长的白发和和服在身后飘动，敌人在远处散开；连击计数为 128\"},{\"title\":\"9\",\"position\":\"右下\",\"count\":1,\"description\":\"从背后拍摄的宁静结尾镜头，女主角独自站在月光下庭院的寺庙门和灯笼前，花瓣飘落，没有主动战斗动作\"}],\"reading_order\":\"从左到右，从上到下\"},\"color_palette\":{\"dominant\":[\"午夜蓝\",\"电光青\",\"银白色\",\"靛蓝\",\"灯笼金\"]},\"camera_and_mood\":\"电影感动作项目，从冷静对峙到拔剑、旋转连击、空中打击、终结技，最后是宁静的余韵；每个面板都像带有可见 HUD 的游戏截图一样构图\"}","imgs":["https://r2.qqsrc.com/images/originals/15374.jpg"]},{"i":8192,"text":"创作一张极具戏剧张力的动漫科幻海报，主角为 {argument name=\"character name\" default=\"Puru Two\"}，灵感源自机甲战争背景下的“强化人”驾驶员。构图采用竖版角色主视觉设计，中心为一名身穿红黑相间流线型驾驶服的女性全身像，以略微仰视的视角自信站立。她留着短碎橘发，两侧留有长刘海，肤色苍白，表情严肃且带有疏离感。她的制服为亮面深红色，配有黑色侧边拼接、高领设计、贴合缝线、前拉链、深色手套、战术腰带，肩部和胸前饰有军事徽章。背景为深邃的太空感抽象空间，融合了黑色、深红、洋红色以及散落的星光质感、能量喷溅效果，营造出一种粗粝的未来主义宣传海报氛围。在中心人物周围添加 3 个嵌入式画格：右上角为透过透明驾驶舱或 HUD 玻璃看到的眼部及上半脸特写，伴有红色界面灯光和小型技术读数；中右侧为一名身穿宽松白裙的少女在明亮朦胧的灰白色背景下的柔和肖像，带有幽灵感；右下角为一只戴着手套的手紧握机械控制杆的特写，背景是发光的驾驶舱仪表盘。在左右边缘添加密集的图形设计元素和排版，结合优雅的衬线英文字体、日文竖排标题、紧凑的技术标签以及机甲规格说明块。包含可见文字，如大标题“PURU TWO”、“NEO ZEON”、“CYBER-NEWTYPE”、“MOBILE SUIT GUNDAM ZZ”、“PSYCHO GUNDAM MK-II”，以及“99.8%”等百分比/状态读数和其他小型控制面板注释。采用高细节的动漫插画风格，运用电影级红色光效、亮面织物高光、锐利的线条、细腻的屏幕反射、分层 UI 叠加，打造出如同奢华科幻角色档案般的高端海报布局。","imgs":["https://r2.qqsrc.com/images/originals/15375.jpg"]},{"i":8193,"text":"{\"type\":\"动漫角色资料卡海报\",\"style\":\"干净精致的日系动漫插画，带有淡紫色设计点缀，白色背景，装饰性花丝边框，优雅的校园偶像参考表布局，高可读性的日文排版，柔和阴影，光泽感双眼，精细线条\",\"subject\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"小原 鞠莉\\\"}\",\"romanized_name\":\"Ohara Mari\",\"series_style\":\"校园偶像动漫角色表\",\"character\":{\"gender\":\"女\",\"age_appearance\":\"高中女生，大龄少女\",\"hair\":{\"color\":\"{argument name=\\\"hair color\\\" default=\\\"金黄色\\\"}\",\"style\":\"长波浪卷发，带有松散的侧编发和卷曲发丝，小呆毛，全身图中顶部有半扎双丸子感\"},\"expression\":\"明亮、自信、充满冒险精神\",\"outfit\":{\"count\":6,\"pieces\":[\"米色水手风校服西装\",\"胸前青色蝴蝶结\",\"灰色水手领，带有海军蓝饰边\",\"灰色百褶裙，下摆处有白色条纹\",\"深色过膝袜\",\"棕色乐福鞋\"]}}},\"layout\":{\"orientation\":\"纵向\",\"sections\":[{\"title\":\"プロフィール\",\"position\":\"右上\",\"count\":12,\"labels\":[\"名前\",\"学年\",\"誕生日\",\"血液型\",\"身長\",\"スリーサイズ\",\"利き手\",\"所属\",\"役割\",\"イメージカラー\",\"特技\",\"好きな食べ物\"]},{\"title\":\"表情集\",\"position\":\"中右\",\"count\":4,\"labels\":[\"眨眼\",\"微笑\",\"兴奋\",\"得意\"]},{\"title\":\"キャラクター紹介\",\"position\":\"左下\",\"count\":1,\"labels\":[\"角色介绍文本框\"]},{\"title\":\"性格・特徴\",\"position\":\"左下（介绍下方）\",\"count\":6,\"labels\":[\"开朗且善于社交\",\"好奇心强且冲动\",\"有主见\",\"情感表达丰富\",\"擅长照顾他人\",\"常因天真烂漫而被调侃\"]},{\"title\":\"好きなこと\",\"position\":\"左下底端\",\"count\":5,\"labels\":[\"去海边\",\"跳舞\",\"体验异国文化\",\"有趣刺激的活动\",\"与朋友聊天\"]},{\"title\":\"苦手なこと\",\"position\":\"中下偏左\",\"count\":5,\"labels\":[\"被繁琐的规则束缚\",\"静止不动\",\"极寒之地\",\"沉闷的氛围\",\"被严厉责骂\"]},{\"title\":\"パラメータ\",\"position\":\"右下\",\"count\":6,\"labels\":[\"表现力・表演 95\",\"沟通能力 90\",\"好奇心・行动力 95\",\"体力・运动能力 70\",\"智力・学力 65\",\"温柔・体贴 85\"]}],\"main_images\":{\"count\":2,\"items\":[\"左侧大尺寸半身肖像，倚靠在户外的阳台栏杆上，背景为蓝天、远处的青山和闪烁的光斑\",\"右上侧全身站立姿势，一手叉腰，另一只手抬起放在脑后\"]},\"footer\":{\"count\":1,\"text\":\"Let’s enjoy! 每一天都是最棒的 Adventure♡\"}},\"text_details\":{\"headline_quote\":\"「人生って、冒険よね！ ワクワクすること、探しに行こ♡」\",\"profile_values\":{\"名前\":\"{argument name=\\\"profile name text\\\" default=\\\"小原 鞠莉 (おはら まり)\\\"}\",\"学年\":\"高中三年级\",\"誕生日\":\"6月13日\",\"血液型\":\"AB型\",\"身長\":\"163cm\",\"スリーサイズ\":\"B・87 W・60 H・84\",\"利き手\":\"右\",\"所属\":\"μ’s（缪斯）\",\"役割\":\"副队长\",\"イメージカラー\":\"紫\",\"特技\":\"英语会话、舞蹈\",\"好きな食べ物\":\"菠萝、焗烤料理\"}},\"color_palette\":{\"count\":5,\"colors\":[\"薰衣草紫\",\"白色\",\"金黄色\",\"青绿色\",\"柔灰色\"]},\"composition\":\"平衡的杂志风格角色档案，带有华丽的紫色边框，左上角有醒目的大号汉字名字，下方附带罗马音，右侧为文字密集的资料卡，中右侧为表情缩略图，右下角为能力雷达图，右下角配有装饰性锚点图标\",\"quality\":\"高分辨率，清晰的印刷级布局，整齐的对齐，优雅可爱的偶像美学\"}","imgs":["https://r2.qqsrc.com/images/originals/15378.jpg"]},{"i":8194,"text":"一张超写实的电影级动作照片，展示了一名年轻人在黄金时刻的日落背景下，在屋顶上腾空而起的瞬间。镜头采用极具戏剧性的低角度拍摄，背景是布满稀疏云层的橙色发光天空。他位于画面中心，双膝弯曲处于空中，头戴编织草帽，身穿一件在风中飘动的 {argument name=\"jacket color\" default=\"亮红色\"} 开衫外套，内搭白色背心，下身穿着深色宽松工装裤，脚蹬粗犷的深色靴子，佩戴叠层项链和露指手套，腰间系着带有发射器皮套的腰带。他的右臂向镜头方向伸出，正在拉动拉条发射一个陀螺玩具，玩具位于画面右侧极近的前景处，呈现出巨大的尺寸和动态模糊效果，以增强深度感和速度感。在底部前景放置一个透明塑料 Beyblade 对战盘，捕捉着日落的温暖反光，盘上清晰可见印制的标志性文字 {argument name=\"brand text\" default=\"BEYBLADE X\"}。城市天际线延伸至下方的背景中，几座高层建筑在靠近地平线的落日余晖中呈现出剪影。光线呈现出强烈的暖色调背光效果，具有明显的轮廓光、电影级对比度、细腻的镜头光晕以及充满动感的织物飘动效果。构图应呈现出 {argument name=\"toy franchise\" default=\"Beyblade X\"} 真人宣传海报的质感，强调活力、青春、速度与城市屋顶竞技感，采用竖版海报格式。","imgs":["https://r2.qqsrc.com/images/originals/15379.jpg"]},{"i":8195,"text":"这是一场电影级的真人动作场景，背景设定在黄昏时分狭窄的欧洲古老石板街上，采用极低角度的特写镜头和戏剧性的广角镜头拍摄。在左前方中心位置，一位灵感来自 {argument name=\"character name\" default=\"路飞\"} 的动态男性战士正向前俯冲，他头戴草帽，身穿敞开的 {argument name=\"jacket color\" default=\"红色\"} 外套、浅色背心和深色长裤。他的身体剧烈扭转，正使用手持发射器发动陀螺战攻击。在右前方，一名身着深色西装、白色衬衫的黑帮风格男子正倾身向前，同样发射着陀螺；他身后还有两名西装男，街道上挤满了围观群众。在画面最前方，两个陀螺在光亮的深色表面上发生碰撞，迸发出耀眼的橙色火花，多道圆形光轨环绕周围，突显出速度感与冲击力。环境氛围浓厚：两侧是风化的石质建筑，街道挤满了观众，阳光照耀下的背景中矗立着宏伟的巴洛克式大教堂圆顶和塔楼。运用强烈的暖琥珀色和铜色灯光、深邃的阴影、高对比度、尘埃与火花颗粒、粗粝的质感、戏剧性的动态模糊、浅景深，营造出史诗级大片的基调。构图应融合地下对决、街头决斗和动漫改编真人版的风格，充满动能、张力与超写实的细节。","imgs":["https://r2.qqsrc.com/images/originals/15380.jpg"]},{"i":8196,"text":"一张奢华的暗黑奇幻动漫插画，描绘了 11 位优雅的年轻女性在深夜的宏伟哥特式图书馆中聚集，构图如同精英魔法学院的集会肖像。房间内堆满了高耸的木制书架、移动梯子、带有神秘金色符号的深红色天鹅绒横幅、雕花护墙板、烛光，最左侧有一盏温暖的台灯，配有红色软垫扶手椅和沙发、成堆的古籍、药水瓶、水晶球、黄铜仪器，以及一扇可以看到深紫色夜空的高大拱窗。整体色调为黑色、深红色、金色和紫色，采用戏剧性的低调照明，阴影浓郁，高光亮丽，营造出一种奢华而阴森的氛围。所有 11 位角色均身穿统一的神秘学院制服：带有金色刺绣和徽章细节的黑色修身夹克、白衬衫、红领带或丝带、多层腰带和链条、短裙或修身下装、黑色过膝袜以及内衬为深红色的黑色斗篷。安排 3 人坐在中间华丽的红色椅子和沙发上，3 人站在后排书架间，3 人在前排坐在地板上或靠近桌子，2 人分别斜靠在最左侧和最右侧边缘。角色的发色和发型各异，包括 {argument name=\"hair color\" default=\"金色\"}、银色、黑色、红色、蓝色、棕色和紫色；发型涵盖长卷发、双马尾、直长发、侧马尾和层次感碎发。赋予每位女性冷静、自信且略带危险的神情，仿佛她们是天才女巫或贵族学生。画面中需包含 6 个清晰可见的魔法效果或正在使用的道具：后方中心处悬浮在举起手上的 1 团红色火焰，右上中心附近站立少女手中持有的 1 个发光的紫色球体，左下方打开的书本上方 1 个旋转的紫色魔法阵，右中位置银发少女膝盖附近 1 团微弱的紫色奥术火焰，最右侧斜靠少女周围 1 圈深紫色烟雾光环，以及中央咖啡桌上 1 个发光的紫色水晶灯或炼金容器。此外，在前景和侧桌上增加 4 个额外的玻璃容器：左下角 1 个水晶球，右下角 1 个高大的红色药水瓶，以及旁边的 2 个小型实验瓶。在膝盖、桌子和地板上放置多个打开和合上的魔法书，总计至少 8 本。中心焦点角色是一位姿态从容的金色头发少女，她坐在最大的扶手椅上，双腿交叠，手靠近脸部，呈现出领袖的姿态。采用高度精细的抛光动漫风格渲染，展现超细腻的织物纹理、复杂的金色饰边、微妙的面部阴影、明亮的眼睛、电影级构图、宽幅群像镜头、奇幻主视觉图品质、忧郁的哥特学院风、魔法姐妹会、清晰对焦、华丽环境，无现代物品。","imgs":["https://r2.qqsrc.com/images/originals/15383.jpg"]},{"i":8197,"text":"一张充满活力的日式航空广告海报，采用光泽感动漫风格，竖构图。画面前景是一位时尚的年轻女性偶像风旅行者，站在机场停机坪上，身后是一架粉白相间的客机。机身和尾翼上印有大号小写字母 {argument name=\"brand name\" default=\"peach\"} 的品牌标识。明亮的蓝天配以蓬松的白云，远处可见机场航站楼，粉色和黄色的几何图形如纸屑般散落，营造出充满活力的促销氛围。角色留着长长的双色发，一侧为黑色，另一侧为鲜艳的粉色，戴着猫耳状发饰或耳机，配有侧边发夹和一根呆毛。她的脸部被中间的矩形模糊块部分遮挡。她佩戴着大型金属耳机、银色颈圈，身穿黑色网眼短款上衣，内搭黑色抹胸，下着黑白不对称短裙（带有两个前扣），肩上滑落着一件亮面超大款粉色飞行员夹克，腿部配有青色腿带。她摆出姿势，一只手伸向观众，另一只手拿着一张印有航空公司名称的粉色登机牌或票卡。在右侧添加第二张悬浮票据，上面用英文写着“Everywhere!”。采用醒目的商业布局，包含 8 个明确的文本区域：左上角 1 个印有 {argument name=\"brand name\" default=\"peach\"} 的大型 Logo，左上方 1 条手写日文标语，中央 1 个写有 {argument name=\"main headline\" default=\"学生割引\"} 的日文促销标题块，1 个写有 {argument name=\"badge text\" default=\"U25限定!\"} 的蓝色圆形徽章，1 个写有 {argument name=\"discount text\" default=\"20%OFF!\"} 的大型折扣提示，底部 3 个圆角白色图标框（每个框内配有小型粉色旅行相关图标和日文说明），以及左下角 1 条写有 {argument name=\"tagline\" default=\"Fly Peach. Love Life.\"} 的英文草书标语。右下角包含一个小型搜索栏样式的 UI 元素，顶部和底部添加额外的对角粉色图形边框，并采用精致的广告设计排版。高饱和度粉色调，青春都市时尚感，动态视角，清晰的赛璐珞渲染配以柔和的喷枪光影，呈现出高级的动漫宣传海报美学。","imgs":["https://r2.qqsrc.com/images/originals/15386.jpg"]},{"i":8198,"text":"一张精美的竖版动漫风格日本航空公司广告海报，用于 {argument name=\"airline name\" default=\"JAPAN AIRLINES\"}，营造出明亮且令人向往的旅行氛围。画面展现了湛蓝的天空，点缀着柔软的白色积云，右上角有强烈的阳光和镜头光晕。一架大型白色商用客机斜向从左下向右上飞行，机尾印有航空公司标志，机身上印有 JAPAN AIRLINES 字样。前景中，在机场观景台的玻璃栏杆前，站着一位动漫风格的女高中生，位置略偏右，背景可见远处的航站楼结构。她留着银金色短波波头，刘海侧分，造型青春时尚，姿态自信从容。她身穿校服，包含 6 件清晰可见的时尚单品：带有荧光绿滚边的深灰色西装外套、白色衬衫、红色条纹领带、带有绿色饰边的黑色百褶裙、带有红色小巧航空标签贴片的黑色单肩包，以及黑色腕饰。她的一只手拿着 2 份旅行证件，分别为一本护照和一张红白配色、与航空公司品牌一致的登机牌或票据册。采用清晰的商业插画渲染、干净的线条、柔和的赛璐珞阴影以及光泽感的海报设计构图。添加日式广告排版和品牌元素，布局如同真实的宣传活动：左上角放置航空公司标志和“JAPAN AIRLINES”；左上角有醒目的大号白色手写体标题，内容为 {argument name=\"main headline\" default=\"飛び出そう、ミライへ。\"}；下方配有较小的白色副标题“いましかできない旅がある。”；左侧中部有一个醒目的红色促销板块，上方写有“JALで行こう!”，下方是一个大的“学生割引”方框，以及一条较小的红色横条“国内線がおトク!”，并配有超大的折扣文字“最大20% OFF!”及下方的免责声明小字。右侧垂直排列 3 个白色圆形标注徽章，配有红色线条图标和日语文案：1 个行李箱图标配文“気軽に旅に出て、新しい自分に出会おう。”，1 个相机图标配文“思い出をたくさんつくろう。”，以及 1 个群体图标配文“仲間との時間を、一生の宝物に。”底部添加一个全宽的深红色页脚横幅，上面印有醒目的大号手写体白色文字 {argument name=\"footer slogan\" default=\"学生の今こそ、世界はもっと広がる。\"}，右侧配有小飞机和云朵涂鸦。在页脚区域内或下方，添加白色小字“詳しくはJALホームページへ”，以及一个包含 {argument name=\"search text\" default=\"JAL 学生割引\"} 的简单搜索栏图形。采用红、白、天蓝的高对比度配色方案，呈现高级的青年营销活动美学，布局简洁现代，充满日式海报风格。","imgs":["https://r2.qqsrc.com/images/originals/15387.jpg"]},{"i":8199,"text":"这是一幅宽银幕企业董事会场景，位于明亮的现代玻璃幕墙办公室中，配有落地窗，窗外隐约可见城市全景。约 {argument name=\"number of attendees\" default=\"22\"} 名不同性别和族裔的商务专业人士坐在呈 U 型排列的浅色木质会议桌旁，每人都穿着正式商务装，许多人正在使用打开的笔记本电脑。在房间前方，一面巨大的壁挂式数字看板占据了构图中心，展示着深蓝色和青色的未来感金融分析界面，共有 12 个清晰可见的数据面板：1 个左上角的大面板，带有标题文本 {argument name=\"dashboard headline\" default=\"SELECTING THE TRACKING TOOL\"} 以及折线图和柱状图；1 个顶部中央的小面板，带有抽象的圆形数据纹理；1 个右上方的面板，带有 92.231 的大数字指标和柱状图；1 个右上角面板，带有折线图和齿轮状界面图标；1 个中左侧条形面板，带有圆形仪表和技术控件；1 个中左侧高面板，带有垂直数据条和圆形叠加层；1 个中央面板，带有三个圆形仪表式读数；1 个中右侧面板，带有紧凑的技术图表和微小的 UI 元素；1 个中右侧水平面板，带有圆形刻度盘和中央数字指示器；1 个下中央面板，带有发光的环形图和波形图；1 个右下角宽面板，带有密集的数据表格；以及 1 个底部中央的小型辅助面板。从房间后方居中视角拍摄，强调对称性和面向屏幕的半圆形就座人员，一名演讲者在显示屏附近呈现剪影。温暖的阳光从左侧射入，在木地板上形成柔和的镜头光晕和长长的阴影。整体图像风格为精致的高端编辑插画，偏向写实的企业概念艺术，采用冷蓝色和暖琥珀色的色调，超精细、整洁、具有未来感、专业且充满雄心。","imgs":["https://r2.qqsrc.com/images/originals/15389.jpg"]}];